const BOOTSTRAP_TOKEN_FILE = path.join(DATA_DIR, 'bootstrap-token.json');

function previousRuntimeBootstrapToken() {
  return previousRuntimeBootstrapTokenFromFile(BOOTSTRAP_TOKEN_FILE);
}

function previousRuntimeBootstrapTokenFromFile(file = '') {
  try {
    const dataDir = path.dirname(path.resolve(file));
    const dataStat = fs.lstatSync(dataDir);
    const tokenStat = fs.lstatSync(file);
    if (!dataStat.isDirectory() || dataStat.isSymbolicLink() || !tokenStat.isFile() || tokenStat.isSymbolicLink()) return '';
    const realProject = fs.realpathSync(PROJECT_ROOT);
    const realData = fs.realpathSync(dataDir);
    const realFile = fs.realpathSync(file);
    if (!isInside(realProject, realData) || !isInside(realData, realFile) || path.resolve(realData) === path.resolve(realFile)) return '';
    const raw = JSON.parse(fs.readFileSync(file, 'utf-8'));
    if (String(raw?.source || '').trim() !== 'runtime') return '';
    const token = String(raw?.bootstrap_token || '').trim();
    if (!token || token.length > 512 || /[\s;,]/.test(token)) return '';
    const root = String(raw?.project_root || '').trim();
    if (root && path.resolve(root) !== path.resolve(PROJECT_ROOT)) return '';
    return token;
  } catch {
    return '';
  }
}

async function persistRuntimeBootstrapToken(token = '') {
  const clean = String(token || '').trim();
  if (!clean) return false;
  try {
    await ensureOrdinaryDataDir();
    await writeJsonAtomic(BOOTSTRAP_TOKEN_FILE, {
      version: 1,
      source: 'runtime',
      project_root: PROJECT_ROOT,
      bootstrap_token: clean,
      updated_at: new Date().toISOString(),
    }, { mode: PRIVATE_FILE_MODE });
    return true;
  } catch {
    return false;
  }
}

