async function clearKeyCachesAfterWxDbMirrorRefresh(mirror = null, reason = 'wxdb_mirror_refreshed') {
  if (!mirror?.refreshed) return;
  const preservesRuntimeState = mirrorRefreshPreservesDbKeyRuntimeState(mirror);
  const runtimeCache = clearDbKeyRuntimeCacheAfterMirrorRefresh(mirror);
  if (preservesRuntimeState) {
    logInfo('db_key_runtime_cache_preserved_for_groups_mirror_refresh', {
      reason,
      account_id: String(mirror.account_id || '').slice(0, 120),
      refresh_reason: String(mirror.refresh_reason || '').slice(0, 120),
      source_snapshot_meta_hash: String(mirror.source_snapshot_meta_hash || '').slice(0, 16),
    });
    return runtimeCache;
  }
  logInfo('db_key_runtime_cache_cleared', {
    reason,
    verified_key_cache_cleared: runtimeCache.verified_key_cache_cleared === true,
    verified_key_cache_retained_as_candidates: runtimeCache.verified_key_cache_retained_as_candidates === true,
    verified_auto_key_cache_cleared: runtimeCache.verified_auto_key_cache_cleared === true,
    candidate_cache_cleared: runtimeCache.candidate_cache_cleared === true,
    failed_auto_scan_cooldown_preserved: runtimeCache.failed_auto_scan_cooldown_preserved === true,
    duplicate_clear_skipped: runtimeCache.reason === 'already_cleared',
    account_id: String(mirror.account_id || '').slice(0, 120),
    refresh_reason: String(mirror.refresh_reason || '').slice(0, 120),
    source_snapshot_meta_hash: String(mirror.source_snapshot_meta_hash || '').slice(0, 16),
  });
}

setWxDbMirrorRefreshListener(async ({ mirror = null } = {}) => {
  clearGroupListResultCache();
  clearDigestGroupContexts();
  const preservesRuntimeState = mirrorRefreshPreservesDbKeyRuntimeState(mirror);
  const clearedPendingValidations = preservesRuntimeState
    ? 0
    : clearPendingManualKeyValidationsForAccount({
      account_id: mirror?.account_id || '',
      account_aliases: [mirror?.id, mirror?.legacy_id, mirror?.wxid].filter(Boolean),
    });
  if (clearedPendingValidations) {
    logInfo('pending_manual_key_validation_cleared', {
      reason: 'wxdb_mirror_refreshed',
      count: clearedPendingValidations,
      account_id: '[redacted]',
    });
  }
  await clearKeyCachesAfterWxDbMirrorRefresh(mirror, 'wxdb_mirror_refreshed');
});

async function handleWxDbMirrorIdentityChanged({ storage_id = '', previous_identity_id = '', identity_id = '' } = {}) {
  const storageId = String(storage_id || '').trim();
  if (!storageId) return;
  const aliases = [storageId, previous_identity_id, identity_id].map(value => String(value || '').trim()).filter(Boolean);
  const invalidatedDigestState = invalidateDigestStateAfterWxDbIdentityChange();
  clearGroupListResultCache();
  clearDigestGroupContexts();
  const clearedPendingValidations = clearPendingManualKeyValidationsForAccount({
    account_id: storageId,
    account_aliases: aliases,
  });
  // The current read proved that the source directory changed accounts, but
  // its caller may still be bound to the old account/rules. Invalidate every
  // in-flight result so no old request can reach AI, output, or cursor writes.
  clearDbKeyRuntimeCache({
    clearVerified: true,
    clearVerifiedAuto: true,
    clearCandidates: true,
    clearFailed: true,
    invalidateActiveReads: true,
  });
  let persistent = { changed: false, key_count: 0 };
  try {
    persistent = await forgetVerifiedWxdbKeysForAccount({ account_id: storageId });
  } catch (e) {
    logWarn('db_key_persistent_cache_clear_after_wxdb_identity_change_failed', {
      account_id: '[redacted]',
      error: sanitizeText(e?.message || String(e)),
    });
  }
  await clearSchedulerAutoKeyFailuresAfterWxDbMirrorRefresh({
    account_id: storageId,
    account_aliases: aliases,
    reason: 'wxdb_mirror_identity_changed',
  }).catch(e => {
    logWarn('scheduler_auto_key_failure_cache_clear_after_wxdb_identity_change_failed', {
      account_id: '[redacted]',
      error: sanitizeText(e?.message || String(e)),
    });
  });
  logInfo('wxdb_mirror_identity_changed', {
    storage_id: '[redacted]',
    previous_identity_id: String(previous_identity_id || '').slice(0, 48),
    identity_id: String(identity_id || '').slice(0, 48),
    pending_manual_key_validations_cleared: clearedPendingValidations,
    persistent_verified_key_cache_cleared: persistent.changed === true,
    persistent_verified_key_count: Math.max(0, Number(persistent.key_count || 0) || 0),
    digest_requests_cancelled: invalidatedDigestState.requests,
    digest_saves_cancelled: invalidatedDigestState.saves,
    digest_save_tickets_revoked: invalidatedDigestState.save_tickets,
    digest_terminal_results_revoked: invalidatedDigestState.terminal_results,
  });
}

setWxDbMirrorIdentityChangeListener(handleWxDbMirrorIdentityChanged);
