    'try { $preferredWindowHandle = [int64](Select-ReusableExplorerItem $Parent ([System.IO.Path]::GetFileName($Target))); $reusedExistingWindow = ($preferredWindowHandle -gt 0) } catch { $preferredWindowHandle = 0; $reusedExistingWindow = $false }',
    'if (-not $reusedExistingWindow) { try { if ($null -ne $ExplorerShell) { [void][System.Runtime.InteropServices.Marshal]::FinalReleaseComObject($ExplorerShell) } } catch {}; $ExplorerShell = $null; $explorerProcess = Start-ExplorerWindow $Target; if ($null -eq $explorerProcess) { throw "资源管理器启动失败" }; Start-Sleep -Milliseconds 1500; $ExplorerShell = New-ExplorerShell; $startedExplorer = $true }',
