    '  try { $urlPath = ExplorerUrlToPath ([string]$Window.LocationURL); if ([string]::Equals($urlPath, $FolderPath, [System.StringComparison]::OrdinalIgnoreCase)) { return $true } } catch {}',
    '  try { foreach ($item in @($Window.Document.SelectedItems())) { $itemParent = [System.IO.Path]::GetDirectoryName([string]$item.Path); if ([string]::Equals($itemParent, $FolderPath, [System.StringComparison]::OrdinalIgnoreCase)) { return $true } } } catch {}',
    '  return $false',
