    file_ext: isPng ? '.png' : '.md',
    file_kind: isPng ? 'png' : 'md',
    artifact_type: isPng ? 'digest_png' : 'text_preview_md',
    file_type: isPng ? 'png' : 'markdown',
    platform: process.platform,
    action_state: 'prepared',
    verification_pending: false,
    verified: false,
    verification_status: 'pending',
    evidence_verified: false,
    cancelled_after_commit: false,
    local_action_committed: false,
    committed_at: '',
    local_action_after_commit_reason: '',
    local_action_after_commit_error: '',
    _commit_evidence_path: localActionCommitEvidenceStoredPath(commitEvidencePath),
