function prepareSaveRenderEvidence(digest = {}, options = {}) {
  return prepareLocalActionOutputEvidence('save_render', {
    ...options,
    digestId: String(digest?.digest_id || '').trim(),
  });
}

function preparePreviewExportEvidence(options = {}) {
  return prepareLocalActionOutputEvidence('export_preview', options);
}

async function markWindowLocalActionCommitted(evidence = null) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return null;
  evidence.local_action_committed = true;
  evidence.committed_at ||= new Date().toISOString();
  evidence.action_state = 'committed';
  evidence.verification_pending = true;
  armWindowActionForegroundIntent(evidence, { refresh: true });
  rememberLocalActionEvidence(evidence);
  const persistence = await persistRecordedLocalActionEvidence(evidence);
  if (persistence.evidence_persisted !== true) {
    throw Object.assign(new Error('资源管理器已启动，但本地动作提交证据未能持久化。'), {
      status: 500,
      code: 'commit_evidence_persist_failed',
      public_code: 'commit_evidence_persist_failed',
      mutation_outcome_unknown: true,
    });
  }
  return persistence;
}

function localActionErrorIsCancellation(error = null) {
  const code = String(error?.code || '').trim();
  return error?.name === 'AbortError'
    || Number(error?.status || 0) === 499
    || ['request_aborted', 'client_disconnected'].includes(code)
    || error?.local_action_after_commit_reason === 'cancelled_after_commit';
}

function markWindowLocalActionPostCommitFailure(evidence = null, error = null) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return evidence;
  const cancelled = evidence.cancelled_after_commit === true || localActionErrorIsCancellation(error);
  if (cancelled) evidence.cancelled_after_commit = true;
  evidence.local_action_after_commit_reason ||= cancelled
    ? 'cancelled_after_commit'
    : (String(error?.local_action_after_commit_reason || '').trim() || 'failed_after_commit');
  evidence.local_action_after_commit_error ||= sanitizeLocalActionUserError(
    error?.local_action_after_commit_error || error?.message || String(error || ''),
  );
  return evidence;
}

async function markWindowLocalActionOutcomeUnknown(evidence = null, error = null) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return evidence;
  evidence.local_action_committed = true;
  evidence.committed_at ||= new Date().toISOString();
  markWindowLocalActionPostCommitFailure(evidence, error);
  const windowsEvidence = String(evidence.platform || process.platform || '').trim() === 'win32';
  evidence.action_state = windowsEvidence ? 'committed' : 'settled';
  evidence.verification_pending = windowsEvidence;
  evidence.verified = false;
  evidence.verification_status = 'warning';
  armWindowActionForegroundIntent(evidence, { refresh: true });
  if (!windowsEvidence) evidence.detached_observation_settled = true;
  rememberLocalActionEvidence(evidence);
  await persistRecordedLocalActionEvidence(evidence);
  return evidence;
}

async function markWindowLocalActionLateFailure(evidence = null, error = null) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return;
  evidence.local_action_committed = true;
  evidence.committed_at ||= new Date().toISOString();
  evidence.action_state = 'settled';
  evidence.verification_pending = false;
  evidence.verified = false;
  evidence.verification_status = 'warning';
  evidence.detached_observation_settled = true;
  evidence.local_action_after_commit_reason = 'failed_after_commit';
  evidence.local_action_after_commit_error = sanitizeLocalActionUserError(error?.message || String(error || '系统打开命令在提交后失败'));
  rememberLocalActionEvidence(evidence);
  await persistRecordedLocalActionEvidence(evidence);
}

async function markNonWindowsLocalActionObservationSettled(evidence = null) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return;
  evidence.detached_observation_settled = true;
  if (String(evidence.platform || process.platform || '').trim() === 'win32') return;
  if (evidence.local_action_after_commit_reason === 'failed_after_commit') return;
  evidence.action_state = 'settled';
  evidence.verification_pending = false;
  evidence.verified = false;
  evidence.verification_status = 'warning';
  rememberLocalActionEvidence(evidence);
  await persistRecordedLocalActionEvidence(evidence);
}

async function discardPreparedLocalActionEvidence(evidence = null) {
  if (!evidence || evidence.local_action_committed === true) return;
  forgetLocalActionEvidence(evidence);
  await LOCAL_ACTION_EVIDENCE_SAVE_QUEUE;
}

function recordRevealEvidence(file, reveal, { actionId = '', cancelledAfterCommit = false, fileVersion = '', digestFileVersion = '', historyItemKey = '', digestId = '', outputDirIdentity = '', settingsRevision = '', existingEvidence = null } = {}) {
  const relativePath = projectRelativePath(file);
  const ext = path.extname(file || '').toLowerCase();
  const evidence = existingEvidence && typeof existingEvidence === 'object' && !Array.isArray(existingEvidence)
    ? existingEvidence
    : {};
  const afterCommitReason = sanitizeText(reveal?.local_action_after_commit_reason || evidence.local_action_after_commit_reason || (cancelledAfterCommit ? 'cancelled_after_commit' : ''));
  const afterCommitError = sanitizeLocalActionUserError(reveal?.local_action_after_commit_error || evidence.local_action_after_commit_error || '');
  const initialVerification = revealVerificationPayload(reveal);
  const targetWindowHandle = Number(reveal?.foreground?.window_handle || evidence._verification_target_window_handle || 0) || 0;
  Object.assign(evidence, {
    kind: 'reveal',
    action_id: normalizeLocalActionId(actionId),
    requested_at: evidence.requested_at || new Date().toISOString(),
    relative_path: relativePath,
    digest_id: sanitizeText(digestId || '').slice(0, 120),
    history_item_key: sanitizeText(historyItemKey || '').slice(0, 160),
    output_dir_identity: normalizeOutputDirRequestIdentity(outputDirIdentity),
    settings_revision: String(settingsRevision || '').trim(),
    file_version: String(fileVersion || '').trim(),
    digest_file_version: String(digestFileVersion || '').trim(),
    file_ext: ext,
    file_kind: ext === '.png' ? 'png' : (ext === '.md' ? 'markdown' : 'other'),
    evidence_ref: localActionEvidenceRef(relativePath),
    platform: reveal?.platform || process.platform,
    opener: reveal?.opener || '',
    mode: reveal?.mode || '',
    reused_existing_window: reveal?.reused_existing_window === true,
    started_explorer: reveal?.started_explorer === true,
    explorer_keeper_started: reveal?.explorer_keeper_started === true,
    explorer_keeper_pid: Number(reveal?.explorer_keeper_pid || 0) || 0,
    explorer_keeper_alive: reveal?.explorer_keeper_alive === true,
    explorer_keeper_exit_code: reveal?.explorer_keeper_exit_code !== null && reveal?.explorer_keeper_exit_code !== undefined && Number.isInteger(Number(reveal.explorer_keeper_exit_code)) ? Number(reveal.explorer_keeper_exit_code) : null,
    launch_status: reveal?.launch_status || evidence.launch_status || '',
    activation_retried: reveal?.activation_retried === true,
    deferred_foreground_nudge_result: reveal?.deferred_foreground_nudge_result === true,
    cancelled_after_commit: cancelledAfterCommit === true,
    local_action_committed: reveal?.local_action_committed === true,
    committed_at: reveal?.local_action_committed === true ? (evidence.committed_at || new Date().toISOString()) : '',
    local_action_after_commit_reason: afterCommitReason,
    local_action_after_commit_error: afterCommitError,
    foreground: process.platform === 'win32' ? (reveal?.foreground || null) : null,
    explorer_selection: process.platform === 'win32'
      ? (reveal?.explorer_selection || { evidence_checked: false, checked_at: '', matched: null })
      : null,
    verified: initialVerification.verified,
    verification_status: initialVerification.status,
    verification: initialVerification.verification,
    _verification_target_path: path.resolve(file || ''),
    _verification_target_window_handle: targetWindowHandle,
  });
  const evidencePlatform = String(evidence.platform || process.platform || '').trim();
  if (evidencePlatform === 'win32' && evidence.local_action_committed === true) {
    armWindowActionForegroundIntent(evidence, { refresh: true });
    // Even a stable sample from the click-local controller must survive one
    // post-response probe. Chromium can otherwise reclaim the foreground just
    // after this endpoint returns.
    armExplorerForegroundHandoffCheck(evidence);
    refreshRevealEvidenceVerification(evidence);
  }
  const needsVerification = (evidencePlatform === 'win32'
      && evidence.local_action_committed === true
      && evidence.verified !== true)
    || (evidencePlatform !== 'win32'
      && evidence.local_action_committed === true
      && /^running_/.test(String(evidence.launch_status || ''))
      && evidence.detached_observation_settled !== true
      && evidence.local_action_after_commit_reason !== 'failed_after_commit');
  evidence.verification_pending = needsVerification;
  evidence.action_state = needsVerification ? 'committed' : 'settled';
  LAST_REVEAL_EVIDENCE = evidence;
  if (evidence.file_kind === 'png') LAST_PNG_REVEAL_EVIDENCE = evidence;
  rememberLocalActionEvidence(evidence);
  if (needsVerification) scheduleRevealSelectionVerification(file, evidence, {
    delayMs: 250,
    activateIfNeeded: windowActionCanRetryForegroundActivation(evidence),
  });
  return evidence;
}

function revealVerificationPayload(reveal = {}) {
  const platform = String(reveal?.platform || process.platform || '').trim();
  const selection = reveal?.explorer_selection || {};
  const foreground = reveal?.foreground || {};
  const windowAmbiguous = explorerTargetWindowAmbiguous(selection);
  const selectionMatched = platform === 'win32'
    && selection.matched === true
    && selection.recheck_matched === true;
  const foregroundStable = platform === 'win32' && foregroundEvidenceReady(foreground);
  const foregroundWindowMatchesSelection = foregroundStable
    && !windowAmbiguous
    && Number(selection.hwnd || 0) > 0
    && Number(foreground.window_handle || 0) === Number(selection.hwnd || 0);
  const tabUnambiguous = (selection.tab_ambiguous === false
    && selection.recheck_tab_ambiguous !== true);
  const verified = reveal?.local_action_committed === true
    && selectionMatched
    && tabUnambiguous
    && foregroundWindowMatchesSelection;
  return {
    verified,
    status: verified ? 'verified' : 'warning',
    verification: {
      selection_matched: selectionMatched,
      explorer_tab_unambiguous: tabUnambiguous,
      tab_ambiguous: selection.tab_ambiguous === true || selection.recheck_tab_ambiguous === true,
      window_ambiguous: windowAmbiguous,
      foreground_window_matches_selection: foregroundWindowMatchesSelection,
      foreground_stable: foregroundStable,
    },
  };
}

function openOutputVerificationPayload(opener = {}) {
  const platform = String(opener?.platform || process.platform || '').trim();
  const foreground = opener?.foreground || {};
  const viewCount = Number(opener?.explorer_view_count || 0) || 0;
  const windowAmbiguous = explorerTargetWindowAmbiguous(opener);
  const foregroundStable = platform === 'win32' && foregroundEvidenceReady(foreground);
  const foregroundWindowConfirmed = foregroundStable
    && Number(foreground.window_handle || 0) > 0
    && !windowAmbiguous;
  const tabUnambiguous = viewCount === 1
    && opener?.tab_ambiguous !== true;
  const verified = opener?.local_action_committed === true
    && tabUnambiguous
    && foregroundWindowConfirmed;
  return {
    verified,
    status: verified ? 'verified' : 'warning',
    verification: {
      explorer_tab_unambiguous: tabUnambiguous,
      tab_ambiguous: opener?.tab_ambiguous === true,
      window_ambiguous: windowAmbiguous,
      foreground_window_confirmed: foregroundWindowConfirmed,
      foreground_stable: foregroundStable,
    },
  };
}

function refreshRevealEvidenceVerification(evidence = null) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return evidence;
  const verification = revealVerificationPayload(evidence);
  evidence.verified = verification.verified;
  evidence.verification_status = verification.status;
  evidence.verification = verification.verification;
  return evidence;
}

function refreshOpenOutputEvidenceVerification(evidence = null) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return evidence;
  const verification = openOutputVerificationPayload(evidence);
  evidence.verified = verification.verified;
  evidence.verification_status = verification.status;
  evidence.verification = verification.verification;
  return evidence;
}

function windowActionVerificationKey(evidence = null) {
  const actionId = normalizeLocalActionId(evidence?.action_id || '');
  const kind = String(evidence?.kind || '').trim();
  return actionId && kind ? `${kind}:${actionId}` : '';
}

function scheduleWindowActionVerification(evidence, verifier, delayMs = 1500) {
  if (process.platform !== 'win32' || !evidence || typeof verifier !== 'function') return;
  const key = windowActionVerificationKey(evidence);
  if (!key || WINDOW_ACTION_VERIFICATION_TIMERS.has(key)) return;
  evidence.verification_pending = true;
  evidence.action_state = evidence.local_action_committed === true ? 'committed' : 'prepared';
  if (!Number.isFinite(Date.parse(evidence.verification_deadline_at || ''))) {
    evidence.verification_deadline_at = new Date(Date.now() + WINDOW_ACTION_VERIFICATION_TIMEOUT_MS).toISOString();
  }
  evidence.verification_attempt_count = Math.max(0, Number(evidence.verification_attempt_count || 0) || 0) + 1;
  rememberLocalActionEvidence(evidence);
  const timer = setTimeout(async () => {
    WINDOW_ACTION_VERIFICATION_TIMERS.delete(key);
    ACTIVE_WINDOW_ACTION_VERIFICATIONS += 1;
    try {
      await verifier().catch(error => {
        logWarn('window_action_verification_failed', {
          kind: String(evidence.kind || ''),
          action_id: normalizeLocalActionId(evidence.action_id || ''),
          error: sanitizeLocalActionUserError(error?.message || String(error)),
        });
        markWindowActionVerificationInternalError(evidence, error);
        void persistRecordedLocalActionEvidence(evidence).catch(persistError => {
          logWarn('window_action_verification_error_persist_failed', {
            kind: String(evidence.kind || ''),
            action_id: normalizeLocalActionId(evidence.action_id || ''),
            error: sanitizeLocalActionUserError(persistError?.message || String(persistError)),
          });
        });
      });
    } finally {
      ACTIVE_WINDOW_ACTION_VERIFICATIONS = Math.max(0, ACTIVE_WINDOW_ACTION_VERIFICATIONS - 1);
    }
  }, Math.max(0, Number(delayMs || 0) || 0));
  timer.unref?.();
  WINDOW_ACTION_VERIFICATION_TIMERS.set(key, timer);
}

function markWindowActionVerificationInternalError(evidence = null, error = null) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return false;
  const committed = evidence.local_action_committed === true;
  evidence.verification_pending = false;
  evidence.action_state = 'settled';
  evidence.verification_status = 'warning';
  evidence.local_action_after_commit_reason ||= committed
    ? 'verification_internal_error_after_commit'
    : 'verification_internal_error_before_commit';
  evidence.local_action_after_commit_error ||= committed
    ? '系统动作已提交，但本地服务在确认文件管理器窗口时发生内部错误；请从任务栏查看，或重新点击后再试。'
    : '本地服务在确认文件管理器窗口时发生内部错误，无法证明系统动作已提交；请重新点击。';
  evidence.verification_internal_error = sanitizeLocalActionUserError(error?.message || String(error || 'unknown verification error'));
  evidence.evidence_persisted = false;
  evidence.evidence_persisted_at = '';
  evidence.evidence_persist_error = '';
  rememberLocalActionEvidence(evidence);
  return true;
}

function windowActionVerificationRetryDelay(evidence = null) {
  const attempt = Math.max(1, Number(evidence?.verification_attempt_count || 1) || 1);
  const retryDelay = WINDOW_ACTION_VERIFICATION_RETRY_DELAYS_MS[Math.min(attempt - 1, WINDOW_ACTION_VERIFICATION_RETRY_DELAYS_MS.length - 1)];
  const handoffAt = Date.parse(String(evidence?.foreground?.post_activation_handoff_not_before || '').trim());
  const handoffDelay = explorerForegroundHandoffCheckPending(evidence?.foreground) && Number.isFinite(handoffAt)
    ? Math.max(0, handoffAt - Date.now() + 80)
    : 0;
  return Math.max(retryDelay, handoffDelay);
}

function windowActionVerificationInitialDelay(evidence = null, delayMs = 1500, nowMs = Date.now()) {
  const requested = Math.max(0, Number(delayMs || 0) || 0);
  if (!explorerForegroundHandoffCheckPending(evidence?.foreground)) return requested;
  const notBefore = Date.parse(String(evidence?.foreground?.post_activation_handoff_not_before || '').trim());
  if (!Number.isFinite(notBefore)) return requested;
  return Math.max(requested, notBefore - Number(nowMs || Date.now()) + 80);
}

function windowActionVerificationCanRetry(evidence = null) {
  if (!evidence || evidence.verified === true || evidence.verification_status === 'verified') return false;
  const deadline = Date.parse(evidence.verification_deadline_at || '');
  return Number.isFinite(deadline) && Date.now() < deadline;
}

function windowActionForegroundActivationAttemptCount(evidence = null) {
  const explicitCount = Math.max(0, Number(evidence?.foreground_activation_retry_count || 0) || 0);
  return explicitCount || (evidence?.activation_retry_attempted === true ? 1 : 0);
}

function armWindowActionForegroundIntent(evidence = null, { refresh = false, nowMs = Date.now() } = {}) {
  if (!evidence
    || String(evidence.platform || process.platform || '').trim() !== 'win32'
    || evidence.local_action_committed !== true
    || evidence.cancelled_after_commit === true
    || evidence.local_action_after_commit_reason === 'cancelled_after_commit') return false;
  const now = Number(nowMs || Date.now()) || Date.now();
  const currentDeadline = Date.parse(String(evidence.foreground_activation_intent_deadline_at || '').trim());
  if (!refresh && Number.isFinite(currentDeadline) && currentDeadline > now) return true;
  evidence.foreground_activation_intent_deadline_at = new Date(now + WINDOWS_EXPLORER_FOREGROUND_INTENT_LEASE_MS).toISOString();
  return true;
}

function windowActionCanRetryForegroundActivation(evidence = null) {
  if (!evidence
    || evidence.cancelled_after_commit === true
    || evidence.local_action_after_commit_reason === 'cancelled_after_commit') return false;
  const intentDeadline = Date.parse(String(evidence.foreground_activation_intent_deadline_at || '').trim());
  if (!Number.isFinite(intentDeadline) || Date.now() >= intentDeadline) return false;
  const attemptCount = windowActionForegroundActivationAttemptCount(evidence);
  if (attemptCount >= WINDOWS_EXPLORER_FOREGROUND_ACTIVATION_MAX_ATTEMPTS) return false;
  const verificationDeadline = Date.parse(evidence?.verification_deadline_at || '');
  if (Number.isFinite(verificationDeadline) && Date.now() >= verificationDeadline) return false;
  if (attemptCount === 0) return true;
  const deadline = Date.parse(evidence?.foreground_activation_retry_deadline_at || '');
  return Number.isFinite(deadline) && Date.now() < deadline;
}

function reserveWindowActionForegroundActivation(evidence = null) {
  if (!evidence || !windowActionCanRetryForegroundActivation(evidence)) return false;
  const attemptCount = windowActionForegroundActivationAttemptCount(evidence) + 1;
  evidence.foreground_activation_retry_count = attemptCount;
  evidence.activation_retry_attempted = true;
  if (attemptCount === 1) {
    evidence.foreground_activation_retry_deadline_at = '';
  }
  return true;
}

function completeWindowActionForegroundActivation(evidence = null) {
  if (!evidence) return false;
  const attemptCount = windowActionForegroundActivationAttemptCount(evidence);
  if (attemptCount <= 0 || attemptCount >= WINDOWS_EXPLORER_FOREGROUND_ACTIVATION_MAX_ATTEMPTS) return false;
  const now = Date.now();
  const verificationDeadline = Date.parse(evidence.verification_deadline_at || '');
  const intentDeadline = Date.parse(String(evidence.foreground_activation_intent_deadline_at || '').trim());
  if (Number.isFinite(verificationDeadline) && now >= verificationDeadline) return false;
  if (!Number.isFinite(intentDeadline) || now >= intentDeadline) return false;
  const retryDeadline = Math.min(
    now + WINDOWS_EXPLORER_FOREGROUND_ACTIVATION_RETRY_WINDOW_MS,
    Number.isFinite(verificationDeadline) ? verificationDeadline : Number.POSITIVE_INFINITY,
    intentDeadline,
  );
  evidence.foreground_activation_retry_deadline_at = new Date(retryDeadline).toISOString();
  return true;
}

function explorerForegroundWasTemporarilyRaised(foreground = {}) {
  return foreground?.handoff_topmost_result === true
    || foreground?.visible_hold_result === true
    || (foreground?.topmost_nudge_result === true && foreground?.deferred_topmost_clear_result === true);
}

function markWindowActionVerificationTimedOut(evidence = null, actionLabel = '文件管理器操作') {
  if (!evidence || evidence.local_action_committed !== true) return;
  if (explorerForegroundWasTemporarilyRaised(evidence.foreground)) {
    evidence.local_action_after_commit_reason ||= 'foreground_not_persistent_after_commit';
    evidence.local_action_after_commit_error ||= `${actionLabel}已打开并已尝试短暂置前，但 Windows 没有确认它持续保持在前台；可从任务栏切换到文件管理器。`;
    return;
  }
  evidence.local_action_after_commit_reason ||= 'verification_timeout_after_commit';
  evidence.local_action_after_commit_error ||= `${actionLabel}已提交，但在 30 秒内仍未确认目标窗口位于最前；请从任务栏查看文件管理器，或重新点击后再试。`;
}

function scheduleRevealSelectionVerification(file, evidence = null, { delayMs = 1500, activateIfNeeded = false } = {}) {
  scheduleWindowActionVerification(
    evidence,
    () => verifyPendingRevealEvidence(file, evidence, { activateIfNeeded }),
    windowActionVerificationInitialDelay(evidence, delayMs),
  );
}

function scheduleOpenOutputVerification(dir, evidence = null, { delayMs = 1500, activateIfNeeded = false } = {}) {
  scheduleWindowActionVerification(
    evidence,
    () => verifyPendingOpenOutputEvidence(dir, evidence, { activateIfNeeded }),
    windowActionVerificationInitialDelay(evidence, delayMs),
  );
}

function settleRestoredNonWindowsActionEvidence(evidence = null) {
  if (!evidence || evidence.verification_pending !== true) return false;
  evidence.verification_pending = false;
  evidence.action_state = 'settled';
  evidence.verified = false;
  evidence.verification_status = 'warning';
  if (evidence.local_action_committed === true) {
    evidence.local_action_after_commit_reason ||= 'service_restarted_after_commit';
    evidence.local_action_after_commit_error ||= '服务在系统打开请求提交后重启；当前平台无法自动确认窗口是否可见，请从系统任务栏或文件管理器查看。';
  } else {
    evidence.local_action_after_commit_reason ||= 'service_restarted_before_commit_confirmation';
    evidence.local_action_after_commit_error ||= '服务在系统打开请求提交确认前重启；为避免重复打开窗口，未自动重放本次操作，请重新点击。';
  }
  rememberLocalActionEvidence(evidence);
  return true;
}

function resumePendingWindowActionVerification(evidence = null, { platform = process.platform } = {}) {
  if (!evidence || evidence.verification_pending !== true) return false;
  const evidencePlatform = String(evidence.platform || '').trim();
  if (platform !== 'win32' || (evidencePlatform && evidencePlatform !== 'win32')) {
    return settleRestoredNonWindowsActionEvidence(evidence);
  }
  const target = localActionVerificationTargetPath(evidence._verification_target_path);
  if (!target) {
    evidence.verification_pending = false;
    evidence.action_state = 'settled';
    evidence.local_action_after_commit_reason ||= 'verification_target_missing';
    evidence.local_action_after_commit_error ||= '服务重启后缺少本地窗口验证目标，无法继续确认资源管理器状态。';
    rememberLocalActionEvidence(evidence);
    return true;
  }
  let changed = false;
  if (evidence.action_state === 'prepared' && evidence.local_action_committed !== true) {
    evidence.local_action_after_commit_reason ||= 'service_restarted_before_commit_confirmation';
    evidence.local_action_after_commit_error ||= '服务在系统动作提交确认前重启；不会自动重复打开资源管理器，正在只读确认现有窗口。';
    changed = true;
  }
  if (evidence.kind === 'reveal') scheduleRevealSelectionVerification(target, evidence, { delayMs: 250 });
  else if (evidence.kind === 'open_output') scheduleOpenOutputVerification(target, evidence, { delayMs: 250 });
  return changed;
}

async function settleWindowActionVerificationEvidence(evidence = null) {
  if (!evidence) return;
  evidence.verification_pending = false;
  evidence.action_state = 'settled';
  evidence.evidence_persisted = false;
  evidence.evidence_persisted_at = '';
  evidence.evidence_persist_error = '';
  rememberLocalActionEvidence(evidence);
  await persistRecordedLocalActionEvidence(evidence);
}

function explorerRevealForegroundActivationEligible(selection = {}) {
  if (explorerTargetWindowAmbiguous(selection)) return false;
  const selectedWindowHandle = Number(selection?.hwnd || 0) || 0;
  if (selection?.matched === true && selectedWindowHandle > 0) return true;
  const folderWindowHandle = Number(selection?.folder_hwnd || 0) || 0;
  return selection?.matched !== true
    && folderWindowHandle > 0
    && !explorerTargetWindowAmbiguous(selection);
}

function boundedRevealForegroundActivationPlan(selection = {}) {
  if (explorerTargetWindowAmbiguous(selection)) return { window_handle: 0, activation_eligible: false };

  const selectedWindowHandle = Number(selection?.hwnd || 0) || 0;
  if (selection?.matched === true && selectedWindowHandle > 0) {
    return { window_handle: selectedWindowHandle, activation_eligible: true };
  }

  // The bounded launcher has just selected this exact file. A second COM
  // readback can race Explorer's tab initialization, so keep this click-local
  // HWND eligible for the stronger foreground handoff without treating it as
  // final success evidence.
  const initialWindowHandle = Number(selection?.initial_hwnd || 0) || 0;
  const initialWindowAmbiguous = explorerTargetWindowAmbiguous({
    window_ambiguous: selection?.initial_window_ambiguous,
    target_window_count: selection?.initial_target_window_count,
    tab_ambiguous: selection?.initial_tab_ambiguous,
  });
  if (selection?.initial_matched === true
    && !initialWindowAmbiguous
    && initialWindowHandle > 0) {
    return { window_handle: initialWindowHandle, activation_eligible: true };
  }

  const folderWindowHandle = Number(selection?.folder_hwnd || 0) || 0;
  const folderWindowAmbiguous = explorerTargetWindowAmbiguous({
    window_ambiguous: selection?.folder_window_ambiguous,
    target_window_count: selection?.folder_window_count,
    tab_ambiguous: selection?.folder_tab_ambiguous,
  });
  if (selection?.matched !== true && folderWindowHandle > 0 && !folderWindowAmbiguous) {
    return { window_handle: folderWindowHandle, activation_eligible: true };
  }
  return { window_handle: 0, activation_eligible: false };
}

function revealSelectionSupportsNativeHandoffProbe(selection = {}, expectedWindowHandle = 0) {
  const expected = Number(expectedWindowHandle || 0) || 0;
  const selected = Number(selection?.hwnd || 0) || 0;
  const rechecked = Number(selection?.recheck_hwnd || 0) || 0;
  return expected > 0
    && selection?.evidence_checked === true
    && selection?.matched === true
    && selection?.recheck_matched === true
    && !explorerTargetWindowAmbiguous(selection)
    && selected === expected
    && rechecked === expected;
}

function openOutputSupportsNativeHandoffProbe(evidence = {}, expectedWindowHandle = 0) {
  const expected = Number(expectedWindowHandle || 0) || 0;
  return expected > 0
    && Number(evidence?.foreground?.window_handle || 0) === expected
    && evidence?.tab_ambiguous !== true
    && !explorerTargetWindowAmbiguous(evidence)
    && Number(evidence?.explorer_view_count || 0) === 1;
}

async function probeNativeExplorerForeground(windowHandle, { signal = null } = {}) {
  const expected = Number(windowHandle || 0) || 0;
  if (process.platform !== 'win32' || expected <= 0 || signal?.aborted) {
    return { available: false, window_exists: false, foreground: null };
  }
  const api = await windowsExplorerNativeApi();
  if (!api || signal?.aborted) return { available: false, window_exists: false, foreground: null };
  const windowExists = nativeExplorerWindowHandles(api).has(expected);
  if (!windowExists) {
    return {
      available: true,
      window_exists: false,
      foreground: {
        window_handle: 0,
        foreground_matched: false,
        foreground_lost_after_match: true,
        foreground_stable_sample_count: 0,
        verification_read_only: true,
      },
    };
  }
  let samples = 0;
  for (let index = 0; index < 3 && !signal?.aborted; index += 1) {
    if (index > 0) await new Promise(resolve => setTimeout(resolve, 80));
    try {
      if (nativeExplorerHwnd(api.GetForegroundWindow()) === expected) samples += 1;
    } catch {}
  }
  return {
    available: true,
    window_exists: true,
    foreground: {
      window_handle: expected,
      foreground_matched: samples >= 3,
      foreground_lost_after_match: samples > 0 && samples < 3,
      foreground_stable_sample_count: samples,
      verification_read_only: true,
    },
  };
}

async function confirmPendingNativeExplorerHandoff(evidence = null, expectedWindowHandle = 0, { signal = null } = {}) {
  if (!evidence
    || !explorerForegroundHandoffCheckPending(evidence.foreground)
    || explorerForegroundHandoffCheckWaiting(evidence.foreground)) return false;
  const probe = await probeNativeExplorerForeground(expectedWindowHandle, { signal });
  if (probe.available !== true || probe.window_exists !== true || !probe.foreground) return false;
  evidence.foreground = mergeReadOnlyExplorerForegroundEvidence(evidence.foreground, probe.foreground);
  return confirmExplorerForegroundHandoffCheck(evidence, probe.foreground, {
    targetWindowHandle: expectedWindowHandle,
  });
}

async function verifyPendingRevealEvidence(file, evidence = null, { activateIfNeeded = false } = {}) {
  if (!evidence) return;
  const previousSelection = evidence.explorer_selection && typeof evidence.explorer_selection === 'object'
    ? evidence.explorer_selection
    : {};
  const previousWindowHandle = Number(
    evidence._verification_target_window_handle
    || previousSelection.initial_hwnd
    || previousSelection.hwnd
    || previousSelection.folder_hwnd
    || previousSelection.recheck_hwnd
    || evidence.foreground?.window_handle
    || 0,
  ) || 0;
  if (revealSelectionSupportsNativeHandoffProbe(previousSelection, previousWindowHandle)) {
    try {
      if (await confirmPendingNativeExplorerHandoff(evidence, previousWindowHandle)) {
        refreshRevealEvidenceVerification(evidence);
        if (evidence.verified === true) {
          await settleWindowActionVerificationEvidence(evidence);
          return;
        }
      }
    } catch (error) {
      logWarn('native_explorer_reveal_handoff_probe_failed', {
        error: sanitizeLocalActionUserError(error?.message || String(error || '')),
      });
    }
  }
  try {
    const selection = await probeExplorerSelection(file, { expectedWindowHandle: previousWindowHandle });
    const windowHandle = Number(selection.hwnd || selection.folder_hwnd || previousWindowHandle || 0) || 0;
    if (selection.bound_window_matched === true && windowHandle > 0) {
      evidence._verification_target_window_handle = windowHandle;
    }
    evidence.explorer_selection = {
      ...selection,
      initial_matched: previousSelection.initial_matched === true || previousSelection.matched === true,
      initial_checked_at: previousSelection.initial_checked_at || previousSelection.checked_at || '',
      initial_hwnd: Number(previousSelection.initial_hwnd || previousSelection.hwnd || previousWindowHandle || 0) || 0,
      initial_tab_ambiguous: previousSelection.initial_tab_ambiguous === true || previousSelection.tab_ambiguous === true,
      initial_window_ambiguous: previousSelection.initial_window_ambiguous === true || previousSelection.window_ambiguous === true,
      initial_target_window_count: Number(previousSelection.initial_target_window_count || previousSelection.target_window_count || 0) || 0,
      rechecked_at: selection.checked_at || new Date().toISOString(),
      recheck_matched: selection.matched === true,
      recheck_tab_ambiguous: selection.tab_ambiguous === true,
      recheck_error: selection.error || '',
    };
    const observedForeground = {
      window_handle: windowHandle,
      foreground_matched: selection.foreground_matched === true,
      foreground_stable_sample_count: Number(selection.foreground_stable_sample_count || 0) || 0,
      foreground_lost_after_match: selection.foreground_lost_after_match === true,
      verification_read_only: true,
    };
    evidence.foreground = mergeReadOnlyExplorerForegroundEvidence(evidence.foreground, observedForeground);
    if (explorerForegroundHandoffCheckPending(evidence.foreground)) {
      confirmExplorerForegroundHandoffCheck(evidence, observedForeground, { targetWindowHandle: windowHandle });
    } else {
      armExplorerForegroundHandoffCheck(evidence);
    }
    // The activation helper revalidates this HWND. Reusing it for the bounded
    // second pass avoids a cold COM probe consuming the retry window.
    while (activateIfNeeded && explorerRevealForegroundActivationEligible(selection) && windowHandle > 0 && !explorerForegroundHandoffCheckWaiting(evidence.foreground) && !foregroundEvidenceReady(evidence.foreground) && reserveWindowActionForegroundActivation(evidence)) {
      try {
        // The target selection was just read back from Explorer. Bridge its
        // input queue to request foreground, but do not focus the file view:
        // this delayed retry must preserve the selected file.
        const activatedForeground = await activateExistingExplorerWindowForeground(windowHandle, { allowInputAttach: true, allowFocus: false, requestTaskbarAttention: true });
        evidence.foreground = mergeExplorerForegroundActivationEvidence(evidence.foreground, activatedForeground);
        armExplorerForegroundHandoffCheck(evidence);
        evidence.activation_retried = true;
      } catch (activationError) {
        evidence.foreground = {
          ...(evidence.foreground && typeof evidence.foreground === 'object' ? evidence.foreground : {}),
          attempted: true,
          activation_retry: true,
          activation_error: sanitizeLocalActionUserError(activationError?.message || String(activationError)),
        };
        evidence.activation_retried = true;
      } finally {
        completeWindowActionForegroundActivation(evidence);
      }
    }
  } catch (error) {
    const recheckError = sanitizeLocalActionUserError(error?.message || String(error));
    evidence.explorer_selection = {
      ...previousSelection,
      evidence_checked: true,
      initial_matched: previousSelection.initial_matched === true || previousSelection.matched === true,
      initial_checked_at: previousSelection.initial_checked_at || previousSelection.checked_at || '',
      initial_tab_ambiguous: previousSelection.initial_tab_ambiguous === true || previousSelection.tab_ambiguous === true,
      matched: false,
      rechecked_at: new Date().toISOString(),
      recheck_matched: null,
      recheck_tab_ambiguous: null,
      recheck_error: recheckError,
    };
    evidence.foreground = mergeReadOnlyExplorerForegroundEvidence(evidence.foreground, {
      window_handle: previousWindowHandle,
      foreground_matched: false,
      foreground_stable_sample_count: 0,
      verification_error: recheckError,
    });
  }
  refreshRevealEvidenceVerification(evidence);
  if (windowActionVerificationCanRetry(evidence)) {
    evidence.verification_pending = true;
    evidence.action_state = evidence.local_action_committed === true ? 'committed' : 'prepared';
    rememberLocalActionEvidence(evidence);
    await persistRecordedLocalActionEvidence(evidence);
    scheduleRevealSelectionVerification(file, evidence, {
      delayMs: windowActionVerificationRetryDelay(evidence),
      // Keep two short retries available after the target appears. The second
      // one runs after the browser has received this click's response.
      activateIfNeeded: windowActionCanRetryForegroundActivation(evidence),
    });
    return;
  }
  if (evidence.verified !== true) markWindowActionVerificationTimedOut(evidence, '在文件夹中显示');
  await settleWindowActionVerificationEvidence(evidence);
}

async function verifyPendingOpenOutputEvidence(dir, evidence = null, { activateIfNeeded = false } = {}) {
  if (!evidence) return;
  const previousWindowHandle = Number(evidence._verification_target_window_handle || evidence.foreground?.window_handle || 0) || 0;
  if (openOutputSupportsNativeHandoffProbe(evidence, previousWindowHandle)) {
    try {
      if (await confirmPendingNativeExplorerHandoff(evidence, previousWindowHandle)) {
        refreshOpenOutputEvidenceVerification(evidence);
        if (evidence.verified === true) {
          await settleWindowActionVerificationEvidence(evidence);
          return;
        }
      }
    } catch (error) {
      logWarn('native_explorer_open_output_handoff_probe_failed', {
        error: sanitizeLocalActionUserError(error?.message || String(error || '')),
      });
    }
  }
  try {
    const folderWindow = await probeExplorerFolderWindow(dir, { expectedWindowHandle: previousWindowHandle });
    const folderPlan = openOutputForegroundActivationPlan(folderWindow);
    const observedWindowHandle = Number(folderWindow.hwnd || 0) || 0;
    const windowHandle = folderPlan.window_handle;
    if (folderWindow.bound_window_matched === true && windowHandle > 0) {
      evidence._verification_target_window_handle = windowHandle;
    }
    const observedForeground = {
      window_handle: observedWindowHandle,
      foreground_matched: folderPlan.activation_eligible && folderWindow.foreground_matched === true,
      foreground_stable_sample_count: Number(folderWindow.foreground_stable_sample_count || 0) || 0,
      foreground_lost_after_match: folderWindow.foreground_lost_after_match === true,
      verification_read_only: true,
    };
    evidence.tab_ambiguous = folderPlan.tab_ambiguous;
    evidence.window_ambiguous = folderPlan.window_ambiguous;
    evidence.target_window_count = Number(folderWindow.target_window_count || 0) || 0;
    evidence.explorer_view_count = folderPlan.explorer_view_count;
    evidence.foreground = mergeReadOnlyExplorerForegroundEvidence(evidence.foreground, observedForeground);
    if (folderPlan.activation_eligible && explorerForegroundHandoffCheckPending(evidence.foreground)) {
      confirmExplorerForegroundHandoffCheck(evidence, observedForeground, { targetWindowHandle: windowHandle });
    } else if (folderPlan.activation_eligible) {
      armExplorerForegroundHandoffCheck(evidence);
    } else {
      evidence.foreground = {
        ...evidence.foreground,
        post_activation_handoff_pending: false,
        post_activation_handoff_confirmed: false,
        post_activation_handoff_not_before: '',
        post_activation_handoff_checked_at: new Date().toISOString(),
        post_activation_handoff_target_matched: false,
      };
    }
    // The activation helper revalidates this HWND. Reusing it for the bounded
    // second pass avoids a cold COM probe consuming the retry window.
    while (activateIfNeeded && folderPlan.activation_eligible && windowHandle > 0 && !explorerForegroundHandoffCheckWaiting(evidence.foreground) && !foregroundEvidenceReady(evidence.foreground) && reserveWindowActionForegroundActivation(evidence)) {
      try {
        const activatedForeground = await activateExistingExplorerWindowForeground(windowHandle, { allowInputAttach: true, allowFocus: true, requestTaskbarAttention: true });
        evidence.foreground = mergeExplorerForegroundActivationEvidence(evidence.foreground, activatedForeground);
        armExplorerForegroundHandoffCheck(evidence);
        evidence.activation_retried = true;
      } catch (activationError) {
        evidence.foreground = {
          ...(evidence.foreground && typeof evidence.foreground === 'object' ? evidence.foreground : {}),
          attempted: true,
          activation_retry: true,
          activation_error: sanitizeLocalActionUserError(activationError?.message || String(activationError)),
        };
        evidence.activation_retried = true;
      } finally {
        completeWindowActionForegroundActivation(evidence);
      }
    }
  } catch (error) {
    evidence.foreground = mergeReadOnlyExplorerForegroundEvidence(evidence.foreground, {
      window_handle: previousWindowHandle,
      foreground_matched: false,
      foreground_stable_sample_count: 0,
      verification_error: sanitizeLocalActionUserError(error?.message || String(error)),
    });
  }
  refreshOpenOutputEvidenceVerification(evidence);
  if (windowActionVerificationCanRetry(evidence)) {
    evidence.verification_pending = true;
    evidence.action_state = evidence.local_action_committed === true ? 'committed' : 'prepared';
    rememberLocalActionEvidence(evidence);
    await persistRecordedLocalActionEvidence(evidence);
    scheduleOpenOutputVerification(dir, evidence, {
      delayMs: windowActionVerificationRetryDelay(evidence),
      // See the reveal path: keep the click-local second retry available after
      // the browser has had a chance to process the initial response.
      activateIfNeeded: windowActionCanRetryForegroundActivation(evidence),
    });
    return;
  }
  if (evidence.verified !== true) markWindowActionVerificationTimedOut(evidence, '打开输出目录');
  await settleWindowActionVerificationEvidence(evidence);
}

function explorerWindowProbeScriptPreamble() {
  return [
    'if (-not ("WxSummary.ExplorerProbe" -as [type])) { $member = "[DllImport(`"user32.dll`")] public static extern bool IsWindow(System.IntPtr hWnd); [DllImport(`"user32.dll`")] public static extern bool IsWindowVisible(System.IntPtr hWnd); [DllImport(`"user32.dll`")] public static extern bool IsIconic(System.IntPtr hWnd); [DllImport(`"user32.dll`")] public static extern System.IntPtr GetAncestor(System.IntPtr hWnd, uint gaFlags); [DllImport(`"user32.dll`")] public static extern System.IntPtr GetForegroundWindow();"; Add-Type -Namespace WxSummary -Name ExplorerProbe -MemberDefinition $member }',
    'if (-not ("WxSummary.ExplorerProbeClass" -as [type])) { $member = "[DllImport(`"user32.dll`")] public static extern int GetClassName(System.IntPtr hWnd, System.Text.StringBuilder lpClassName, int nMaxCount);"; Add-Type -Namespace WxSummary -Name ExplorerProbeClass -MemberDefinition $member }',
    'function Test-ExplorerWindowHwnd([System.IntPtr]$Hwnd) { try { if (-not [WxSummary.ExplorerProbe]::IsWindow($Hwnd) -or -not [WxSummary.ExplorerProbe]::IsWindowVisible($Hwnd)) { return $false }; $className = New-Object System.Text.StringBuilder 64; [void][WxSummary.ExplorerProbeClass]::GetClassName($Hwnd, $className, $className.Capacity); $name = $className.ToString(); return ($name -eq "CabinetWClass" -or $name -eq "ExploreWClass") } catch { return $false } }',
    'function Resolve-ExplorerWindowHwnd([int64]$Value) {',
    '  if ($Value -le 0) { return 0 }',
    '  try {',
    '    $ptr = [System.IntPtr]::new($Value)',
    '    if (-not (Test-ExplorerWindowHwnd $ptr)) { return 0 }',
    '    return $ptr.ToInt64()',
    '  } catch { return 0 }',
    '}',
  ];
}

function probeExplorerSelection(targetPath, { signal = null, expectedWindowHandle = 0 } = {}) {
  const encodedPath = Buffer.from(path.resolve(targetPath || ''), 'utf-8').toString('base64');
  const expectedHwnd = Math.max(0, Number(expectedWindowHandle || 0) || 0);
  const script = [
    '$ErrorActionPreference = "Stop"',
    `$Target = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('${encodedPath}'))`,
    '$Parent = [System.IO.Path]::GetDirectoryName($Target)',
    `$ExpectedWindowHandle = [int64]${expectedHwnd}`,
    ...explorerWindowProbeScriptPreamble(),
    '$matched = $false; $selectedCount = 0; $expectedSelectedCount = 0; $matchedHwnd = 0; $folderHwnd = 0; $expectedFolderMatched = $false; $expectedSelectionMatched = $false; $viewCounts = @{}; $matchedHwnds = @{}; $folderHwnds = @{}',
    '$foregroundHwnd = 0; try { $foregroundHwnd = [int64][WxSummary.ExplorerProbe]::GetForegroundWindow() } catch {}',
    '$shell = New-Object -ComObject Shell.Application',
    'foreach ($window in @($shell.Windows())) {',
    '  try {',
    '    $rawHwnd = 0; try { $rawHwnd = [int64]$window.HWND } catch { try { $rawHwnd = [int64]$window.Hwnd } catch {} }',
    '    $hwnd = Resolve-ExplorerWindowHwnd $rawHwnd',
    '    if ($hwnd -le 0) { continue }',
    '    $viewKey = [string]$hwnd; $viewCounts[$viewKey] = 1 + [int]($viewCounts[$viewKey])',
    '    $folder = ""; try { $folder = [string]$window.Document.Folder.Self.Path } catch {}',
    '    if ([string]::Equals($folder, $Parent, [System.StringComparison]::OrdinalIgnoreCase)) { $folderHwnds[[string]$hwnd] = $true; if ($ExpectedWindowHandle -gt 0 -and $hwnd -eq $ExpectedWindowHandle) { $expectedFolderMatched = $true; $folderHwnd = $hwnd } elseif ($ExpectedWindowHandle -le 0 -and ($folderHwnd -le 0 -or $hwnd -eq $foregroundHwnd)) { $folderHwnd = $hwnd } }',
    '    foreach ($item in @($window.Document.SelectedItems())) {',
    '      $p = [string]$item.Path',
    '      if ([string]::Equals($p, $Target, [System.StringComparison]::OrdinalIgnoreCase)) { $matched = $true; $selectedCount += 1; $matchedHwnds[[string]$hwnd] = $true; if ($ExpectedWindowHandle -gt 0 -and $hwnd -eq $ExpectedWindowHandle) { $expectedSelectionMatched = $true; $expectedSelectedCount += 1; $matchedHwnd = $hwnd } elseif ($ExpectedWindowHandle -le 0 -and ($matchedHwnd -le 0 -or $hwnd -eq $foregroundHwnd)) { $matchedHwnd = $hwnd } }',
    '    }',
    '  } catch {}',
    '}',
    'if ($ExpectedWindowHandle -gt 0) { $matched = $expectedSelectionMatched; $selectedCount = $expectedSelectedCount; if (-not $expectedSelectionMatched) { $matchedHwnd = 0 }; if (-not $expectedFolderMatched) { $folderHwnd = 0 } }',
    'if ($matched -and $matchedHwnd -le 0) { $matched = $false }',
    '$matchedWindowCount = $matchedHwnds.Count; $folderWindowCount = $folderHwnds.Count',
    '$boundFolderMatched = $ExpectedWindowHandle -gt 0 -and $expectedFolderMatched',
    '$boundSelectionMatched = $ExpectedWindowHandle -gt 0 -and $expectedSelectionMatched',
    '$matchedViewCount = if ($matchedHwnd -gt 0) { [int]($viewCounts[[string]$matchedHwnd]) } else { 0 }',
    '$folderViewCount = if ($folderHwnd -gt 0) { [int]($viewCounts[[string]$folderHwnd]) } else { 0 }',
    '$folderTabAmbiguous = $folderViewCount -gt 1; $folderWindowAmbiguous = $folderWindowCount -gt 1 -and -not $boundFolderMatched',
    '$tabAmbiguous = if ($matched) { $matchedViewCount -gt 1 } else { $folderTabAmbiguous }',
    '$windowAmbiguous = if ($matched) { $matchedWindowCount -gt 1 -and -not $boundSelectionMatched } else { $folderWindowAmbiguous }',
    '$targetWindowCount = if ($matched) { $matchedWindowCount } else { $folderWindowCount }',
    '$foregroundStableSampleCount = 0; if ($matched -and $matchedHwnd -gt 0) { $matchedPtr = [System.IntPtr]::new($matchedHwnd); for ($i = 0; $i -lt 3; $i++) { if ($i -gt 0) { Start-Sleep -Milliseconds 160 }; if ([WxSummary.ExplorerProbe]::GetForegroundWindow() -eq $matchedPtr) { $foregroundStableSampleCount += 1 } } }',
    '[pscustomobject]@{ checked_at = (Get-Date).ToUniversalTime().ToString("o"); matched = $matched; selected_count = $selectedCount; hwnd = $matchedHwnd; folder_hwnd = $folderHwnd; folder_view_count = $folderViewCount; folder_tab_ambiguous = $folderTabAmbiguous; folder_window_ambiguous = $folderWindowAmbiguous; folder_window_count = $folderWindowCount; tab_ambiguous = $tabAmbiguous; window_ambiguous = $windowAmbiguous; target_window_count = $targetWindowCount; explorer_view_count = $matchedViewCount; bound_window_matched = ($boundSelectionMatched -or $boundFolderMatched); foreground_stable_sample_count = $foregroundStableSampleCount; foreground_matched = ($foregroundStableSampleCount -ge 3) } | ConvertTo-Json -Compress',
  ].join('; ');
  return runLocalActionPowerShell(script, {
    signal,
    queueLane: 'probe',
    timeoutMs: 10_000,
    timeoutMessage: 'Explorer 选中文件验证超时',
    abortMessage: 'Explorer 选中文件验证已取消。',
    actionLabel: '验证 Explorer 选中文件',
    checkDesktopSession: true,
  }).then(({ stdout }) => {
    try {
      const parsed = JSON.parse(stdout || '{}');
      return {
        evidence_checked: true,
        checked_at: parsed.checked_at || new Date().toISOString(),
        matched: parsed.matched === true,
        selected_count: Number(parsed.selected_count || 0) || 0,
        hwnd: Number(parsed.hwnd || 0) || 0,
        folder_hwnd: Number(parsed.folder_hwnd || 0) || 0,
        folder_view_count: Number(parsed.folder_view_count || 0) || 0,
        folder_tab_ambiguous: parsed.folder_tab_ambiguous === true,
        folder_window_ambiguous: parsed.folder_window_ambiguous === true,
        folder_window_count: Number(parsed.folder_window_count || 0) || 0,
        tab_ambiguous: parsed.tab_ambiguous === true,
        window_ambiguous: parsed.window_ambiguous === true,
        target_window_count: Number(parsed.target_window_count || 0) || 0,
        explorer_view_count: Number(parsed.explorer_view_count || 0) || 0,
        bound_window_matched: parsed.bound_window_matched === true,
        foreground_stable_sample_count: Number(parsed.foreground_stable_sample_count || 0) || 0,
        foreground_matched: parsed.foreground_matched === true,
        error: '',
      };
    } catch (error) {
      throw Object.assign(new Error(`Explorer 选中文件验证输出不可解析：${error.message}`), { status: 500 });
    }
  });
}

function probeExplorerFolderWindow(dir, { signal = null, expectedWindowHandle = 0 } = {}) {
  const encodedDir = Buffer.from(path.resolve(dir || ''), 'utf-8').toString('base64');
  const expectedHwnd = Math.max(0, Number(expectedWindowHandle || 0) || 0);
  const script = [
    '$ErrorActionPreference = "Stop"',
    `$Dir = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('${encodedDir}'))`,
    `$ExpectedWindowHandle = [int64]${expectedHwnd}`,
    ...explorerWindowProbeScriptPreamble(),
    '$windowHandle = 0; $expectedWindowMatched = $false; $viewCounts = @{}; $matchingHwnds = @{}',
    '$foregroundHwnd = 0; try { $foregroundHwnd = [int64][WxSummary.ExplorerProbe]::GetForegroundWindow() } catch {}',
    '$shell = New-Object -ComObject Shell.Application',
    'foreach ($window in @($shell.Windows())) {',
    '  try {',
    '    $rawHwnd = 0; try { $rawHwnd = [int64]$window.HWND } catch { try { $rawHwnd = [int64]$window.Hwnd } catch {} }',
    '    $candidateHwnd = Resolve-ExplorerWindowHwnd $rawHwnd',
    '    if ($candidateHwnd -le 0) { continue }',
    '    $viewKey = [string]$candidateHwnd; $viewCounts[$viewKey] = 1 + [int]($viewCounts[$viewKey])',
    '    $folder = [string]$window.Document.Folder.Self.Path',
    '    if (-not [string]::Equals($folder, $Dir, [System.StringComparison]::OrdinalIgnoreCase)) { continue }',
    '    $matchingHwnds[[string]$candidateHwnd] = $true',
    '    if ($ExpectedWindowHandle -gt 0 -and $candidateHwnd -eq $ExpectedWindowHandle) { $expectedWindowMatched = $true; $windowHandle = $candidateHwnd } elseif ($ExpectedWindowHandle -le 0 -and ($windowHandle -le 0 -or $candidateHwnd -eq $foregroundHwnd)) { $windowHandle = $candidateHwnd }',
    '  } catch {}',
    '}',
    '$targetWindowCount = $matchingHwnds.Count',
    '$boundWindowMatched = $ExpectedWindowHandle -gt 0 -and $expectedWindowMatched',
    '$matchedWindowViewCount = if ($windowHandle -gt 0) { [int]($viewCounts[[string]$windowHandle]) } else { 0 }',
    '$viewCount = $matchedWindowViewCount',
    '$tabAmbiguous = $matchedWindowViewCount -gt 1',
    '$windowAmbiguous = $targetWindowCount -gt 1 -and -not $boundWindowMatched',
    '$foregroundStableSampleCount = 0; if ($windowHandle -gt 0) { $windowPtr = [System.IntPtr]::new($windowHandle); for ($i = 0; $i -lt 3; $i++) { if ($i -gt 0) { Start-Sleep -Milliseconds 160 }; if ([WxSummary.ExplorerProbe]::GetForegroundWindow() -eq $windowPtr) { $foregroundStableSampleCount += 1 } } }',
    '[pscustomobject]@{ checked_at = (Get-Date).ToUniversalTime().ToString("o"); hwnd = $windowHandle; tab_ambiguous = $tabAmbiguous; window_ambiguous = $windowAmbiguous; target_window_count = $targetWindowCount; explorer_view_count = $viewCount; bound_window_matched = $boundWindowMatched; foreground_stable_sample_count = $foregroundStableSampleCount; foreground_matched = ($foregroundStableSampleCount -ge 3) } | ConvertTo-Json -Compress',
  ].join('; ');
  return runLocalActionPowerShell(script, {
    signal,
    queueLane: 'probe',
    timeoutMs: 10_000,
    timeoutMessage: 'Explorer 输出目录验证超时',
    abortMessage: 'Explorer 输出目录验证已取消。',
    actionLabel: '验证 Explorer 输出目录窗口',
    checkDesktopSession: true,
  }).then(({ stdout }) => {
    try {
      const parsed = JSON.parse(stdout || '{}');
      return {
        hwnd: Number(parsed.hwnd || 0) || 0,
        tab_ambiguous: parsed.tab_ambiguous === true,
        window_ambiguous: parsed.window_ambiguous === true,
        target_window_count: Number(parsed.target_window_count || 0) || 0,
        explorer_view_count: Number(parsed.explorer_view_count || 0) || 0,
        bound_window_matched: parsed.bound_window_matched === true,
        foreground_stable_sample_count: Number(parsed.foreground_stable_sample_count || 0) || 0,
        foreground_matched: parsed.foreground_matched === true,
      };
    } catch (error) {
      throw Object.assign(new Error(`Explorer 输出目录验证输出不可解析：${error.message}`), { status: 500 });
    }
  });
}

function explorerTopmostHoldRemainingMs(foreground = {}, nowMs = Date.now()) {
  const untilValues = [
    Date.parse(String(foreground?.topmost_hold_until || '').trim()),
    Date.parse(String(foreground?.handoff_topmost_until || '').trim()),
  ].filter(Number.isFinite);
  if (!untilValues.length) return 0;
  return Math.max(0, Math.max(...untilValues) - Number(nowMs || 0));
}

function explorerTopmostHoldActive(foreground = {}, nowMs = Date.now()) {
  const normalHoldActive = (foreground?.visible_hold_result === true || foreground?.topmost_nudge_result === true)
    && foreground?.deferred_topmost_clear_result === true
    && explorerTopmostHoldRemainingMs(foreground, nowMs) > 0;
  const handoffUntilMs = Date.parse(String(foreground?.handoff_topmost_until || '').trim());
  const handoffHoldActive = foreground?.handoff_topmost_result === true
    && foreground?.handoff_topmost_clear_result === true
    && Number.isFinite(handoffUntilMs)
    && Math.max(0, handoffUntilMs - Number(nowMs || 0)) > 0;
  return normalHoldActive || handoffHoldActive;
}

function explorerForegroundHandoffCheckPending(foreground = {}) {
  return foreground?.post_activation_handoff_pending === true
    && foreground?.post_activation_handoff_confirmed !== true;
}

function explorerForegroundHandoffCheckWaiting(foreground = {}, nowMs = Date.now()) {
  if (!explorerForegroundHandoffCheckPending(foreground)) return false;
  const notBeforeMs = Date.parse(String(foreground?.post_activation_handoff_not_before || '').trim());
  return Number.isFinite(notBeforeMs) && Number(nowMs || 0) < notBeforeMs;
}

function armExplorerForegroundHandoffCheck(evidence = null, { nowMs = Date.now() } = {}) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return false;
  const foreground = evidence.foreground && typeof evidence.foreground === 'object' ? evidence.foreground : {};
  if (foreground.post_activation_handoff_confirmed === true) return false;
  // Test the activation sample itself. The pending marker below intentionally
  // makes the normal readiness predicate false until the delayed recheck.
  if (!foregroundEvidenceReady({
    ...foreground,
    post_activation_handoff_pending: false,
    post_activation_handoff_confirmed: true,
  })) return false;
  const dueAt = new Date(Number(nowMs || Date.now()) + WINDOWS_EXPLORER_POST_ACTIVATION_HANDOFF_DELAY_MS).toISOString();
  evidence.foreground = {
    ...foreground,
    post_activation_handoff_pending: true,
    post_activation_handoff_confirmed: false,
    post_activation_handoff_not_before: dueAt,
    post_activation_handoff_checked_at: '',
  };
  return true;
}

function confirmExplorerForegroundHandoffCheck(evidence = null, observed = {}, { targetWindowHandle = 0, nowMs = Date.now() } = {}) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return false;
  const foreground = evidence.foreground && typeof evidence.foreground === 'object' ? evidence.foreground : {};
  if (!explorerForegroundHandoffCheckPending(foreground)) return false;
  const checkedAtMs = Number(nowMs || Date.now());
  if (explorerForegroundHandoffCheckWaiting(foreground, checkedAtMs)) return false;
  const observedWindowHandle = Number(observed?.window_handle || 0) || 0;
  const expectedWindowHandle = Number(targetWindowHandle || foreground.window_handle || 0) || 0;
  const targetMatches = expectedWindowHandle <= 0 || (observedWindowHandle > 0 && observedWindowHandle === expectedWindowHandle);
  const stable = foregroundEvidenceReady({
    ...foreground,
    ...(observed && typeof observed === 'object' ? observed : {}),
    post_activation_handoff_pending: false,
    post_activation_handoff_confirmed: true,
  });
  const confirmed = stable && targetMatches;
  evidence.foreground = {
    ...foreground,
    post_activation_handoff_pending: !confirmed,
    post_activation_handoff_confirmed: confirmed,
    post_activation_handoff_checked_at: new Date(checkedAtMs).toISOString(),
    post_activation_handoff_target_matched: targetMatches,
  };
  return confirmed;
}

function mergeReadOnlyExplorerForegroundEvidence(previous = {}, observed = {}, nowMs = Date.now()) {
  const observedStable = observed?.foreground_matched === true
    && Number(observed?.foreground_stable_sample_count || 0) >= 3;
  const topmostHoldActive = !observedStable && explorerTopmostHoldActive(previous, nowMs);
  const previousTopmostHoldUntil = String(previous?.topmost_hold_until || '').trim();
  const previousTopmostHoldMs = Number(previous?.topmost_hold_ms || 0) || 0;
  const staleConfirmedHandoff = !observedStable
    && previous?.post_activation_handoff_confirmed === true;
  return {
    ...(previous && typeof previous === 'object' ? previous : {}),
    ...(observed && typeof observed === 'object' ? observed : {}),
    attempted: previous?.attempted === true,
    visible_hold_result: topmostHoldActive,
    foreground_hold_result: false,
    deferred_topmost_clear_result: previous?.deferred_topmost_clear_result === true,
    topmost_hold_ms: previousTopmostHoldMs,
    topmost_hold_until: previousTopmostHoldUntil,
    post_hold_matched: false,
    // A later read-only sample is authoritative. Do not allow a previous
    // successful handoff to make a new activation skip its delayed recheck.
    post_activation_handoff_pending: staleConfirmedHandoff ? false : previous?.post_activation_handoff_pending === true,
    post_activation_handoff_confirmed: staleConfirmedHandoff ? false : previous?.post_activation_handoff_confirmed === true,
    post_activation_handoff_not_before: staleConfirmedHandoff ? '' : String(previous?.post_activation_handoff_not_before || '').trim(),
    post_activation_handoff_checked_at: staleConfirmedHandoff ? '' : String(previous?.post_activation_handoff_checked_at || '').trim(),
    post_activation_handoff_target_matched: staleConfirmedHandoff ? false : previous?.post_activation_handoff_target_matched === true,
    verification_read_only: true,
  };
}

function mergeExplorerForegroundActivationEvidence(previous = {}, activated = {}) {
  return {
    ...(previous && typeof previous === 'object' ? previous : {}),
    ...(activated && typeof activated === 'object' ? activated : {}),
    attempted: previous?.attempted === true || activated?.attempted === true,
    taskbar_attention_requested: previous?.taskbar_attention_requested === true
      || activated?.taskbar_attention_requested === true,
    activation_retry: true,
    verification_read_only: false,
  };
}

function legacyActivateExistingExplorerWindowForeground(windowHandle, { signal = null } = {}) {
  const hwnd = Number(windowHandle || 0) || 0;
  if (hwnd <= 0) {
    return Promise.resolve({
      attempted: false,
      activation_retry: true,
      window_handle: 0,
      foreground_matched: false,
      foreground_stable_sample_count: 0,
      verification_read_only: false,
    });
  }
  const powerShellPath = requireWindowsSystemCommandPath('powershell.exe', '重试置前 Explorer 窗口');
  const script = [
    '$ErrorActionPreference = "Stop"',
    `$WindowHandle = [int64]${hwnd}`,
    `$PowerShellExe = ${powerShellSingleQuotedLiteral(powerShellPath)}`,
    ...explorerWindowProbeScriptPreamble(),
    'if (-not ("WxSummary.ExplorerActivation" -as [type])) { $member = "[DllImport(`"user32.dll`")] public static extern bool ShowWindowAsync(System.IntPtr hWnd, int nCmdShow); [DllImport(`"user32.dll`")] public static extern bool SetForegroundWindow(System.IntPtr hWnd); [DllImport(`"user32.dll`")] public static extern bool BringWindowToTop(System.IntPtr hWnd); [DllImport(`"user32.dll`")] public static extern bool SetWindowPos(System.IntPtr hWnd, System.IntPtr hWndInsertAfter, int X, int Y, int cx, int cy, uint uFlags); [DllImport(`"user32.dll`")] public static extern void SwitchToThisWindow(System.IntPtr hWnd, bool fAltTab); [DllImport(`"user32.dll`")] public static extern bool AllowSetForegroundWindow(int dwProcessId);"; Add-Type -Namespace WxSummary -Name ExplorerActivation -MemberDefinition $member }',
    '$WindowHandle = [int64](Resolve-ExplorerWindowHwnd $WindowHandle)',
    'if ($WindowHandle -le 0) { [pscustomobject]@{ attempted = $false; activation_retry = $true; window_handle = 0; foreground_matched = $false; foreground_stable_sample_count = 0; verification_read_only = $false } | ConvertTo-Json -Compress; exit 0 }',
    '$ptr = [System.IntPtr]::new($WindowHandle)',
    '$flags = [uint32](0x0001 -bor 0x0002 -bor 0x0010 -bor 0x0040)',
    'function Start-DeferredTopmostClear([int64]$TargetWindowHandle) {',
    '  if ($TargetWindowHandle -le 0) { return $false }',
    '  try {',
    `    $clearTemplate = [System.Text.Encoding]::Unicode.GetString([Convert]::FromBase64String('${WINDOWS_DEFERRED_TOPMOST_CLEAR_SCRIPT_B64}'))`,
    '    $clearScript = $clearTemplate.Replace("__WX_HWND__", [string]$TargetWindowHandle)',
    '    $encodedClear = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($clearScript))',
    '    $process = Start-Process -FilePath $PowerShellExe -ArgumentList @("-NoProfile","-WindowStyle","Hidden","-ExecutionPolicy","Bypass","-EncodedCommand",$encodedClear) -WindowStyle Hidden -PassThru',
    '    return ($null -ne $process)',
    '  } catch { return $false }',
    '}',
    '$deferredTopmostClearResult = Start-DeferredTopmostClear $WindowHandle',
    '$allowResult = [WxSummary.ExplorerActivation]::AllowSetForegroundWindow(-1)',
    '$topmostResult = [WxSummary.ExplorerActivation]::SetWindowPos($ptr, [System.IntPtr]::new(-1), 0, 0, 0, 0, $flags)',
    '$showResult = [WxSummary.ExplorerActivation]::ShowWindowAsync($ptr, 9)',
    '$bringResult = [WxSummary.ExplorerActivation]::BringWindowToTop($ptr)',
    '$setResult = [WxSummary.ExplorerActivation]::SetForegroundWindow($ptr)',
    '$switchAttempted = $false; try { [WxSummary.ExplorerActivation]::SwitchToThisWindow($ptr, $true); $switchAttempted = $true } catch {}',
    '$stableBeforeClear = 0; for ($i = 0; $i -lt 3; $i++) { if ($i -gt 0) { Start-Sleep -Milliseconds 180 }; if ([WxSummary.ExplorerProbe]::GetForegroundWindow() -eq $ptr) { $stableBeforeClear += 1 } }',
    '$topmostClearResult = $false; $normalTopResult = $false; $visibleHoldResult = $false; $topmostHoldMs = 0; $topmostHoldUntil = ""; $stable = 0; $foregroundMatched = ($stableBeforeClear -ge 3)',
    'if ($foregroundMatched) {',
    '  $topmostClearResult = [WxSummary.ExplorerActivation]::SetWindowPos($ptr, [System.IntPtr]::new(-2), 0, 0, 0, 0, $flags)',
    '  $normalTopResult = [WxSummary.ExplorerActivation]::SetWindowPos($ptr, [System.IntPtr]::Zero, 0, 0, 0, 0, $flags)',
    '  for ($i = 0; $i -lt 3; $i++) { if ($i -gt 0) { Start-Sleep -Milliseconds 180 }; if ([WxSummary.ExplorerProbe]::GetForegroundWindow() -eq $ptr) { $stable += 1 } }',
    '  $foregroundMatched = ($stable -ge 3)',
    '} elseif ($deferredTopmostClearResult -and $topmostResult) {',
    '  $visibleHoldResult = $true',
    `  $topmostHoldMs = ${WINDOWS_EXPLORER_TOPMOST_HOLD_MS}`,
    '  $topmostHoldUntil = (Get-Date).ToUniversalTime().AddMilliseconds($topmostHoldMs).ToString("o")',
    '} else {',
    '  $topmostClearResult = [WxSummary.ExplorerActivation]::SetWindowPos($ptr, [System.IntPtr]::new(-2), 0, 0, 0, 0, $flags)',
    '  $normalTopResult = [WxSummary.ExplorerActivation]::SetWindowPos($ptr, [System.IntPtr]::Zero, 0, 0, 0, 0, $flags)',
    '}',
    '[pscustomobject]@{ attempted = $true; activation_retry = $true; window_handle = $WindowHandle; show_result = $showResult; topmost_nudge_result = $topmostResult; topmost_clear_result = $topmostClearResult; normal_top_result = $normalTopResult; visible_hold_result = $visibleHoldResult; foreground_hold_result = $false; allow_foreground_result = $allowResult; set_foreground_result = $setResult; bring_to_top_result = $bringResult; switch_attempted = $switchAttempted; deferred_topmost_clear_result = $deferredTopmostClearResult; topmost_hold_ms = $topmostHoldMs; topmost_hold_until = $topmostHoldUntil; post_hold_matched = $foregroundMatched; foreground_lost_after_match = ($stableBeforeClear -gt 0 -and -not $foregroundMatched); foreground_stable_sample_count = $stable; foreground_matched = $foregroundMatched; verification_read_only = $false } | ConvertTo-Json -Compress',
  ].join('; ');
  return runLocalActionPowerShell(script, {
    signal,
    queueLane: 'window',
    timeoutMs: 7000,
    timeoutMessage: 'Explorer 置前重试超时',
    abortMessage: 'Explorer 置前重试已取消。',
    actionLabel: '重试置前 Explorer 窗口',
  }).then(({ stdout }) => {
    try {
      const parsed = JSON.parse(stdout || '{}');
      return {
        attempted: parsed.attempted === true,
        activation_retry: true,
        window_handle: Number(parsed.window_handle || 0) || 0,
        show_result: parsed.show_result === true,
        topmost_nudge_result: parsed.topmost_nudge_result === true,
        topmost_clear_result: parsed.topmost_clear_result === true,
        normal_top_result: parsed.normal_top_result === true,
        visible_hold_result: parsed.visible_hold_result === true,
        foreground_hold_result: false,
        allow_foreground_result: parsed.allow_foreground_result === true,
        set_foreground_result: parsed.set_foreground_result === true,
        bring_to_top_result: parsed.bring_to_top_result === true,
        switch_attempted: parsed.switch_attempted === true,
        deferred_topmost_clear_result: parsed.deferred_topmost_clear_result === true,
        topmost_hold_ms: Number(parsed.topmost_hold_ms || 0) || 0,
        topmost_hold_until: String(parsed.topmost_hold_until || '').trim(),
        post_hold_matched: parsed.post_hold_matched === true,
        foreground_lost_after_match: parsed.foreground_lost_after_match === true,
        foreground_stable_sample_count: Number(parsed.foreground_stable_sample_count || 0) || 0,
        foreground_matched: parsed.foreground_matched === true,
        verification_read_only: false,
      };
    } catch (error) {
      throw Object.assign(new Error(`Explorer 置前重试输出不可解析：${error.message}`), { status: 500 });
    }
  });
}

function activateExistingExplorerWindowForeground(windowHandle, { signal = null, allowInputAttach = false, allowFocus = false, requestTaskbarAttention = false } = {}) {
  const hwnd = Number(windowHandle || 0) || 0;
  const inputAttachEnabled = allowInputAttach === true;
  const focusEnabled = inputAttachEnabled && allowFocus === true;
  const taskbarAttentionEnabled = requestTaskbarAttention === true;
  if (hwnd <= 0) {
    return Promise.resolve({
      attempted: false,
      activation_retry: true,
      window_handle: 0,
      foreground_matched: false,
      foreground_stable_sample_count: 0,
      taskbar_attention_requested: false,
      verification_read_only: false,
    });
  }
  const powerShellPath = requireWindowsSystemCommandPath('powershell.exe', '重试置前 Explorer 窗口');
  const script = [
    '$ErrorActionPreference = "Stop"',
    `$WindowHandle = [int64]${hwnd}`,
    `$PowerShellExe = ${powerShellSingleQuotedLiteral(powerShellPath)}`,
    `$AllowInputAttach = ${inputAttachEnabled ? '$true' : '$false'}`,
    `$AllowFocus = ${focusEnabled ? '$true' : '$false'}`,
    `$RequestTaskbarAttention = ${taskbarAttentionEnabled ? '$true' : '$false'}`,
    ...explorerWindowProbeScriptPreamble(),
    'if (-not ("WxSummary.FastExplorerActivation" -as [type])) { $member = "[StructLayout(LayoutKind.Sequential)] public struct FlashWindowInfo { public uint cbSize; public System.IntPtr hwnd; public uint dwFlags; public uint uCount; public uint dwTimeout; } [DllImport(`"user32.dll`")] public static extern bool FlashWindowEx(ref FlashWindowInfo pwfi); [DllImport(`"user32.dll`")] public static extern bool ShowWindowAsync(System.IntPtr hWnd, int nCmdShow); [DllImport(`"user32.dll`")] public static extern bool SetForegroundWindow(System.IntPtr hWnd); [DllImport(`"user32.dll`")] public static extern bool BringWindowToTop(System.IntPtr hWnd); [DllImport(`"user32.dll`")] public static extern bool SetWindowPos(System.IntPtr hWnd, System.IntPtr hWndInsertAfter, int X, int Y, int cx, int cy, uint uFlags); [DllImport(`"user32.dll`")] public static extern bool AllowSetForegroundWindow(int dwProcessId); [DllImport(`"user32.dll`")] public static extern uint GetWindowThreadProcessId(System.IntPtr hWnd, out uint processId); [DllImport(`"kernel32.dll`")] public static extern uint GetCurrentThreadId(); [DllImport(`"user32.dll`")] public static extern bool AttachThreadInput(uint idAttach, uint idAttachTo, bool fAttach); [DllImport(`"user32.dll`")] public static extern System.IntPtr SetFocus(System.IntPtr hWnd); [DllImport(`"user32.dll`")] public static extern void SwitchToThisWindow(System.IntPtr hWnd, bool fAltTab);"; Add-Type -Namespace WxSummary -Name FastExplorerActivation -MemberDefinition $member }',
    'if (-not ("WxSummary.FastExplorerActivationWindow" -as [type])) { $member = "[DllImport(`"user32.dll`")] public static extern System.IntPtr SetActiveWindow(System.IntPtr hWnd);"; Add-Type -Namespace WxSummary -Name FastExplorerActivationWindow -MemberDefinition $member }',
    'function Start-FastExplorerTopmostRelease([int64]$TargetWindowHandle) {',
    '  if ($TargetWindowHandle -le 0) { return $false }',
    '  try {',
    `    $clearTemplate = [System.Text.Encoding]::Unicode.GetString([Convert]::FromBase64String('${WINDOWS_DEFERRED_TOPMOST_CLEAR_SCRIPT_B64}'))`,
    '    $clearScript = $clearTemplate.Replace("__WX_HWND__", [string]$TargetWindowHandle)',
    '    $encodedClear = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($clearScript))',
    '    $process = Start-Process -FilePath $PowerShellExe -ArgumentList @("-NoProfile","-WindowStyle","Hidden","-ExecutionPolicy","Bypass","-EncodedCommand",$encodedClear) -WindowStyle Hidden -PassThru',
    '    return ($null -ne $process)',
    '  } catch { return $false }',
    '}',
    '$WindowHandle = [int64](Resolve-ExplorerWindowHwnd $WindowHandle)',
    'if ($WindowHandle -le 0) { [pscustomobject]@{ attempted = $false; activation_retry = $true; window_handle = 0; foreground_matched = $false; foreground_stable_sample_count = 0; verification_read_only = $false } | ConvertTo-Json -Compress; exit 0 }',
    '$ptr = [System.IntPtr]::new($WindowHandle); $flags = [uint32](0x0001 -bor 0x0002 -bor 0x0040)',
    '$allowResult = $false; $showResult = $false; $restoreAttempted = $false; $topmostResult = $false; $bringResult = $false; $setResult = $false; $setActiveResult = $false; $setFocusResult = $false; $attachInputResult = $false; $attachedForeground = $false; $attachedTarget = $false; [uint32]$foregroundThread = 0; [uint32]$targetThread = 0; [uint32]$currentThread = 0; $clearResult = $false; $normalTopResult = $false; $deferredClearResult = $false; $visibleHoldResult = $false; $topmostHoldMs = 0; $topmostHoldUntil = ""; $taskbarAttentionRequested = $false',
    // File reveal may bridge input queues to pass Windows' foreground lock, but
    // must not focus the Explorer view because that can clear its selection.
    // Opening a directory has no selected-file state and may also set focus.
    '$wasMinimized = $false; try { $wasMinimized = [WxSummary.ExplorerProbe]::IsIconic($ptr) } catch {}',
    'if ($wasMinimized) { $restoreAttempted = $true; try { $showResult = [WxSummary.FastExplorerActivation]::ShowWindowAsync($ptr, 9) } catch {} }',
    'try { $allowResult = [WxSummary.FastExplorerActivation]::AllowSetForegroundWindow(-1) } catch {}',
    'if ($AllowInputAttach) { try { $foregroundWindow = [WxSummary.ExplorerProbe]::GetForegroundWindow(); [uint32]$foregroundProcessId = 0; [uint32]$targetProcessId = 0; $foregroundThread = [uint32][WxSummary.FastExplorerActivation]::GetWindowThreadProcessId($foregroundWindow, [ref]$foregroundProcessId); $targetThread = [uint32][WxSummary.FastExplorerActivation]::GetWindowThreadProcessId($ptr, [ref]$targetProcessId); $currentThread = [uint32][WxSummary.FastExplorerActivation]::GetCurrentThreadId(); if ($foregroundThread -gt 0 -and $foregroundThread -ne $currentThread) { $attachedForeground = [WxSummary.FastExplorerActivation]::AttachThreadInput($currentThread, $foregroundThread, $true) }; if ($targetThread -gt 0 -and $targetThread -ne $currentThread -and $targetThread -ne $foregroundThread) { $attachedTarget = [WxSummary.FastExplorerActivation]::AttachThreadInput($currentThread, $targetThread, $true) }; $attachInputResult = ($attachedForeground -or $attachedTarget) } catch {} }',
    'try { $bringResult = [WxSummary.FastExplorerActivation]::BringWindowToTop($ptr) } catch {}',
    // This changes only the parent window's activation. Do not focus the file
    // view here: revealing a file must retain Explorer's selection.
    'if ($attachInputResult) { try { $setActiveResult = ([WxSummary.FastExplorerActivationWindow]::SetActiveWindow($ptr) -ne [System.IntPtr]::Zero) } catch {} }',
    'try { $setResult = [WxSummary.FastExplorerActivation]::SetForegroundWindow($ptr) } catch {}',
    'if ($AllowFocus -and $attachInputResult) { try { $setFocusResult = ([WxSummary.FastExplorerActivation]::SetFocus($ptr) -ne [System.IntPtr]::Zero) } catch {} }',
    'Start-Sleep -Milliseconds 180',
    '$stable = 0; for ($sample = 0; $sample -lt 3; $sample++) { Start-Sleep -Milliseconds 100; if ([WxSummary.ExplorerProbe]::GetForegroundWindow() -eq $ptr) { $stable += 1 } }',
    '$switchAttempted = $false',
    // The browser can reclaim focus after the initial Explorer launch. This is
    // still a direct user-clicked, target-bound retry, so use the same
    // top-level window switch as the launch path before falling back to a
    // temporary topmost nudge. It does not focus the file view.
    'if ($stable -lt 3) { try { [WxSummary.FastExplorerActivation]::SwitchToThisWindow($ptr, $true); $switchAttempted = $true } catch {}; if ($switchAttempted) { Start-Sleep -Milliseconds 180; $stable = 0; for ($sample = 0; $sample -lt 3; $sample++) { Start-Sleep -Milliseconds 100; if ([WxSummary.ExplorerProbe]::GetForegroundWindow() -eq $ptr) { $stable += 1 } } } }',
    'if ($attachedTarget) { try { [void][WxSummary.FastExplorerActivation]::AttachThreadInput($currentThread, $targetThread, $false) } catch {} }; if ($attachedForeground) { try { [void][WxSummary.FastExplorerActivation]::AttachThreadInput($currentThread, $foregroundThread, $false) } catch {} }',
    'if ($stable -lt 3) {',
    '  try { $deferredClearResult = Start-FastExplorerTopmostRelease $WindowHandle } catch {}',
    '  if ($deferredClearResult) {',
    '    try { $topmostResult = [WxSummary.FastExplorerActivation]::SetWindowPos($ptr, [System.IntPtr]::new(-1), 0, 0, 0, 0, $flags) } catch {}',
    '    try { [void][WxSummary.FastExplorerActivation]::BringWindowToTop($ptr); $setResult = ([WxSummary.FastExplorerActivation]::SetForegroundWindow($ptr) -or $setResult) } catch {}',
    '    Start-Sleep -Milliseconds 300',
    '    $stable = 0; for ($sample = 0; $sample -lt 3; $sample++) { Start-Sleep -Milliseconds 100; if ([WxSummary.ExplorerProbe]::GetForegroundWindow() -eq $ptr) { $stable += 1 } }',
    '  }',
    '}',
    'if ($topmostResult -and $deferredClearResult) {',
    '  $visibleHoldResult = $true',
    `  $topmostHoldMs = ${WINDOWS_EXPLORER_TOPMOST_HOLD_MS}`,
    '  $topmostHoldUntil = (Get-Date).ToUniversalTime().AddMilliseconds($topmostHoldMs).ToString("o")',
    '}',
    // FlashWindowEx returns the previous active state, not a success signal.
    // Treat a completed native call as an attention request and never as focus proof.
    'if ($RequestTaskbarAttention -and $stable -lt 3) { try { $flash = [Activator]::CreateInstance([type]"WxSummary.FastExplorerActivation+FlashWindowInfo"); $flash.cbSize = [uint32][System.Runtime.InteropServices.Marshal]::SizeOf($flash); $flash.hwnd = $ptr; $flash.dwFlags = [uint32]0x00000002; $flash.uCount = [uint32]3; $flash.dwTimeout = 0; [void][WxSummary.FastExplorerActivation]::FlashWindowEx([ref]$flash); $taskbarAttentionRequested = $true } catch {} }',
    '[pscustomobject]@{ attempted = $true; activation_retry = $true; window_handle = $WindowHandle; show_result = $showResult; restore_attempted = $restoreAttempted; topmost_nudge_result = $topmostResult; topmost_clear_result = $clearResult; normal_top_result = $normalTopResult; visible_hold_result = $visibleHoldResult; foreground_hold_result = $false; allow_foreground_result = $allowResult; set_foreground_result = $setResult; set_active_result = $setActiveResult; set_focus_result = $setFocusResult; bring_to_top_result = $bringResult; input_attach_allowed = $AllowInputAttach; focus_allowed = $AllowFocus; attach_input_result = $attachInputResult; switch_attempted = $switchAttempted; deferred_topmost_clear_result = $deferredClearResult; topmost_hold_ms = $topmostHoldMs; topmost_hold_until = $topmostHoldUntil; post_hold_matched = ($stable -ge 3); foreground_lost_after_match = ($stable -gt 0 -and $stable -lt 3); foreground_stable_sample_count = $stable; foreground_matched = ($stable -ge 3); taskbar_attention_requested = $taskbarAttentionRequested; verification_read_only = $false } | ConvertTo-Json -Compress',
  ].join('; ');
  return runLocalActionPowerShell(script, {
    signal,
    queueLane: 'window',
    timeoutMs: 15_000,
    timeoutMessage: 'Explorer 置前重试超时',
    abortMessage: 'Explorer 置前重试已取消。',
    actionLabel: '重试置前 Explorer 窗口',
    settleOnProcessExit: false,
    checkDesktopSession: true,
  }).then(({ stdout }) => {
    const parsed = JSON.parse(stdout || '{}');
    return {
      attempted: parsed.attempted === true,
      activation_retry: true,
      window_handle: Number(parsed.window_handle || 0) || 0,
      show_result: parsed.show_result === true,
      restore_attempted: parsed.restore_attempted === true,
      topmost_nudge_result: parsed.topmost_nudge_result === true,
      topmost_clear_result: parsed.topmost_clear_result === true,
      normal_top_result: parsed.normal_top_result === true,
      visible_hold_result: parsed.visible_hold_result === true,
      foreground_hold_result: false,
      allow_foreground_result: parsed.allow_foreground_result === true,
      set_foreground_result: parsed.set_foreground_result === true,
      set_active_result: parsed.set_active_result === true,
      set_focus_result: parsed.set_focus_result === true,
      bring_to_top_result: parsed.bring_to_top_result === true,
      input_attach_allowed: parsed.input_attach_allowed === true,
      focus_allowed: parsed.focus_allowed === true,
      attach_input_result: parsed.attach_input_result === true,
      switch_attempted: parsed.switch_attempted === true,
      deferred_topmost_clear_result: parsed.deferred_topmost_clear_result === true,
      topmost_hold_ms: Number(parsed.topmost_hold_ms || 0) || 0,
      topmost_hold_until: String(parsed.topmost_hold_until || '').trim(),
      post_hold_matched: parsed.post_hold_matched === true,
      foreground_lost_after_match: parsed.foreground_lost_after_match === true,
      foreground_stable_sample_count: Number(parsed.foreground_stable_sample_count || 0) || 0,
      foreground_matched: parsed.foreground_matched === true,
      taskbar_attention_requested: parsed.taskbar_attention_requested === true,
      verification_read_only: false,
    };
  });
}

function probeExistingExplorerWindowForeground(windowHandle, { signal = null } = {}) {
  const hwnd = Number(windowHandle || 0) || 0;
  if (hwnd <= 0) return Promise.resolve({ window_handle: 0, foreground_matched: false, foreground_stable_sample_count: 0, verification_read_only: true });
  const script = [
    `$WindowHandle = [int64]${hwnd}`,
    ...explorerWindowProbeScriptPreamble(),
    '$WindowHandle = [int64](Resolve-ExplorerWindowHwnd $WindowHandle)',
    'if ($WindowHandle -le 0) { [pscustomobject]@{ window_handle = 0; foreground_matched = $false; foreground_lost_after_match = $false; foreground_stable_sample_count = 0; verification_read_only = $true } | ConvertTo-Json -Compress; exit 0 }',
    '$ptr = [System.IntPtr]::new($WindowHandle)',
    '$stable = 0; for ($i = 0; $i -lt 3; $i++) { if ($i -gt 0) { Start-Sleep -Milliseconds 160 }; if ([WxSummary.ExplorerProbe]::GetForegroundWindow() -eq $ptr) { $stable += 1 } }',
    '$foregroundMatched = ($stable -ge 3)',
    '[pscustomobject]@{ window_handle = $WindowHandle; foreground_lost_after_match = ($stable -gt 0 -and -not $foregroundMatched); foreground_stable_sample_count = $stable; foreground_matched = $foregroundMatched; verification_read_only = $true } | ConvertTo-Json -Compress',
  ].join('; ');
  return runLocalActionPowerShell(script, {
    signal,
    queueLane: 'probe',
    timeoutMs: 5000,
    timeoutMessage: 'Explorer 前台状态只读确认超时',
    abortMessage: 'Explorer 前台状态只读确认已取消。',
    actionLabel: '只读确认 Explorer 前台窗口',
    checkDesktopSession: true,
  }).then(({ stdout }) => {
    try {
      const parsed = JSON.parse(stdout || '{}');
      return {
        window_handle: Number(parsed.window_handle || 0) || 0,
        foreground_lost_after_match: parsed.foreground_lost_after_match === true,
        foreground_stable_sample_count: Number(parsed.foreground_stable_sample_count || 0) || 0,
        foreground_matched: parsed.foreground_matched === true,
        verification_read_only: true,
      };
    } catch (error) {
      throw Object.assign(new Error(`Explorer 前台状态只读确认输出不可解析：${error.message}`), { status: 500 });
    }
  });
}

function normalizedClipboardSize(value) {
  const width = Number(value?.width || 0);
  const height = Number(value?.height || 0);
  if (!Number.isInteger(width) || !Number.isInteger(height) || width <= 0 || height <= 0) return null;
  return { width, height };
}

function systemClipboardEvidencePayload(kind = '', actionId = '', value = {}, { commitEvidencePath = '' } = {}) {
  const cleanKind = String(kind || '').trim();
  if (!['clipboard_copy', 'text_clipboard_copy'].includes(cleanKind)) {
    throw new TypeError('系统剪贴板动作类型无效');
  }
  const purpose = cleanKind === 'text_clipboard_copy' && String(value?.purpose || 'text') === 'file_path'
    ? 'file_path'
    : (cleanKind === 'text_clipboard_copy' ? 'text' : 'image');
  const relativePath = purpose === 'text'
    ? ''
    : String(value?.relative_path || '').trim().replace(/\\/g, '/').slice(0, 240);
  const evidence = {
    kind: cleanKind,
    action_id: normalizeLocalActionId(actionId),
    requested_at: new Date().toISOString(),
    platform: process.platform,
    method: 'system_clipboard',
    purpose,
    action_state: 'prepared',
    verification_pending: true,
    local_action_committed: false,
    clipboard_verified: false,
    evidence_verified: false,
    cancelled_after_commit: false,
    local_action_after_commit_reason: '',
    local_action_after_commit_error: '',
  };
  if (purpose === 'text') {
    evidence.content_bytes = Math.max(0, Math.min(
      SYSTEM_TEXT_CLIPBOARD_MAX_BYTES,
      Number(value?.content_bytes || 0) || 0,
    ));
  } else if (relativePath) {
    Object.assign(evidence, {
      relative_path: relativePath,
      digest_id: sanitizeText(value?.digest_id || '').slice(0, 120),
      history_item_key: sanitizeText(value?.history_item_key || '').slice(0, 160),
      file_version: String(value?.file_version || '').trim(),
      digest_file_version: String(value?.digest_file_version || '').trim(),
      output_dir_identity: normalizeOutputDirRequestIdentity(value?.output_dir_identity || ''),
      settings_revision: String(value?.settings_revision || '').trim().slice(0, 320),
      file_ext: String(value?.file_ext || '').trim().slice(0, 20),
      file_kind: sanitizeText(value?.file_kind || '').slice(0, 80),
      evidence_ref: localActionEvidenceRef(relativePath),
    });
  }
  const storedCommitEvidencePath = localActionCommitEvidenceStoredPath(commitEvidencePath);
  if (storedCommitEvidencePath) evidence._commit_evidence_path = storedCommitEvidencePath;
  return evidence;
}

function prepareSystemClipboardEvidence(kind = '', actionId = '', value = {}, options = {}) {
  return rememberLocalActionEvidence(systemClipboardEvidencePayload(kind, actionId, value, options));
}

async function persistPreparedSystemClipboardEvidence(evidence = null) {
  const persistence = await persistRecordedLocalActionEvidence(evidence);
  if (persistence.evidence_persisted === true) return persistence;
  const commitEvidencePath = localActionCommitEvidenceStoredPath(evidence?._commit_evidence_path);
  await discardPreparedLocalActionEvidence(evidence);
  await cleanupLocalActionCommitEvidence(commitEvidencePath);
  throw Object.assign(new Error('无法持久化系统剪贴板恢复记录，已停止写入剪贴板。'), {
    status: 503,
    code: 'system_clipboard_prepare_persist_failed',
    public_code: 'system_clipboard_prepare_persist_failed',
  });
}

async function markSystemClipboardEvidenceCommitted(evidence = null) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) {
    throw new TypeError('缺少系统剪贴板提交证据');
  }
  evidence.local_action_committed = true;
  evidence.committed_at ||= new Date().toISOString();
  evidence.action_state = 'committed';
  evidence.verification_pending = true;
  rememberLocalActionEvidence(evidence);
  const persistence = await persistRecordedLocalActionEvidence(evidence);
  if (persistence.evidence_persisted !== true) {
    throw Object.assign(new Error('系统剪贴板已写入，但提交证据未能持久化。'), {
      status: 500,
      code: 'commit_evidence_persist_failed',
      public_code: 'commit_evidence_persist_failed',
      mutation_outcome_unknown: true,
    });
  }
  return persistence;
}

function systemClipboardCopyResultFromEvidence(evidence = null) {
  return {
    clipboard: normalizedClipboardSize(evidence?.clipboard),
    clipboard_verified: evidence?.clipboard_verified === true,
    evidence_verified: evidence?.evidence_verified === true,
    local_action_committed: evidence?.local_action_committed === true,
    method: sanitizeText(evidence?.method || 'system_clipboard'),
    local_action_after_commit_reason: sanitizeText(evidence?.local_action_after_commit_reason || ''),
    local_action_after_commit_error: sanitizeLocalActionUserError(evidence?.local_action_after_commit_error || ''),
  };
}

async function recoverPreparedSystemClipboardEvidenceAfterFailure(evidence = null, error = null) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return null;
  const commitEvidencePath = localActionCommitEvidenceStoredPath(evidence._commit_evidence_path);
  if (commitEvidencePath) {
    await reconcileRestoredLocalActionCommitEvidence(evidence, { restarted: false }).catch(reconcileError => {
      logWarn('system_clipboard_commit_reconcile_failed', {
        action_id: normalizeLocalActionId(evidence.action_id || ''),
        error: sanitizeText(reconcileError?.message || String(reconcileError)),
      });
    });
  }
  if (evidence.local_action_committed === true) {
    evidence.verification_pending = false;
    evidence.action_state = 'settled';
    evidence.local_action_after_commit_reason ||= error?.status === 499 || error?.name === 'AbortError'
      ? 'cancelled_after_commit'
      : 'failed_after_commit';
    evidence.local_action_after_commit_error ||= sanitizeLocalActionUserError(error?.message || String(error || '系统剪贴板写入后的收尾失败'));
    rememberLocalActionEvidence(evidence);
    await persistRecordedLocalActionEvidence(evidence);
    return systemClipboardCopyResultFromEvidence(evidence);
  }
  if (!commitEvidencePath) {
    evidence.action_state = 'outcome_unknown';
    evidence.verification_pending = false;
    evidence.local_action_after_commit_reason ||= 'system_clipboard_outcome_unknown';
    evidence.local_action_after_commit_error ||= '系统剪贴板命令中断，当前平台没有动作提交标记；不会自动重放写入，请粘贴确认后再决定是否重试。';
    rememberLocalActionEvidence(evidence);
    await persistRecordedLocalActionEvidence(evidence);
    return null;
  }
  await cleanupLocalActionCommitEvidence(commitEvidencePath);
  await discardPreparedLocalActionEvidence(evidence);
  return null;
}

async function persistSettledSystemClipboardEvidence(evidence = null) {
  const persistence = await persistRecordedLocalActionEvidence(evidence);
  if (persistence.evidence_persisted !== true) return persistence;
  const commitEvidencePath = localActionCommitEvidenceStoredPath(evidence?._commit_evidence_path);
  if (!commitEvidencePath || !(await cleanupLocalActionCommitEvidence(commitEvidencePath))) return persistence;
  delete evidence._commit_evidence_path;
  rememberLocalActionEvidence(evidence);
  const cleanupPersistence = await persistRecordedLocalActionEvidence(evidence);
  return cleanupPersistence.evidence_persisted === true ? cleanupPersistence : persistence;
}

function recordClipboardCopyEvidence(file, copied = {}, { actionId = '', fileVersion = '', digestFileVersion = '', historyItemKey = '', digestId = '', outputDirIdentity = '', settingsRevision = '', existingEvidence = null } = {}) {
  const relativePath = projectRelativePath(file);
  const evidence = existingEvidence && typeof existingEvidence === 'object' && !Array.isArray(existingEvidence)
    ? existingEvidence
    : {};
  Object.assign(evidence, {
    kind: 'clipboard_copy',
    action_id: normalizeLocalActionId(actionId),
    copied_at: new Date().toISOString(),
    relative_path: relativePath,
    digest_id: sanitizeText(digestId || '').slice(0, 120),
    history_item_key: sanitizeText(historyItemKey || '').slice(0, 160),
    file_version: String(fileVersion || '').trim(),
    digest_file_version: String(digestFileVersion || '').trim(),
    output_dir_identity: normalizeOutputDirRequestIdentity(outputDirIdentity),
    settings_revision: String(settingsRevision || '').trim().slice(0, 320),
    evidence_ref: localActionEvidenceRef(relativePath),
    clipboard: normalizedClipboardSize(copied?.clipboard),
    platform: process.platform,
    method: sanitizeText(copied?.method || evidence.method || 'system_clipboard'),
    client_reported: copied?.client_reported === true,
    browser_clipboard_reported: copied?.browser_clipboard_reported === true || copied?.client_reported === true,
    local_action_committed: copied?.local_action_committed === true || evidence.local_action_committed === true,
    committed_at: evidence.committed_at || (copied?.local_action_committed === true ? new Date().toISOString() : ''),
    action_state: 'settled',
    verification_pending: false,
    clipboard_verified: copied?.clipboard_verified === true,
    evidence_verified: copied?.evidence_verified === true || copied?.clipboard_verified === true,
    cancelled_after_commit: copied?.cancelled_after_commit === true,
    local_action_after_commit_reason: sanitizeText(copied?.local_action_after_commit_reason || evidence.local_action_after_commit_reason || ''),
    local_action_after_commit_error: sanitizeLocalActionUserError(copied?.local_action_after_commit_error || evidence.local_action_after_commit_error || ''),
  });
  LAST_CLIPBOARD_COPY_EVIDENCE = rememberLocalActionEvidence(evidence);
  return LAST_CLIPBOARD_COPY_EVIDENCE;
}

function recordTextClipboardCopyEvidence(copied = {}, {
  actionId = '',
  cancelledAfterCommit = false,
  purpose = 'text',
  relativePath = '',
  digestId = '',
  historyItemKey = '',
  fileVersion = '',
  digestFileVersion = '',
  outputDirIdentity = '',
  settingsRevision = '',
  fileKind = '',
  existingEvidence = null,
} = {}) {
  const filePathPurpose = String(purpose || 'text') === 'file_path';
  const cleanRelativePath = filePathPurpose
    ? String(relativePath || '').trim().replace(/\\/g, '/').slice(0, 240)
    : '';
  const evidence = existingEvidence && typeof existingEvidence === 'object' && !Array.isArray(existingEvidence)
    ? existingEvidence
    : {};
  Object.assign(evidence, {
    kind: 'text_clipboard_copy',
    purpose: filePathPurpose ? 'file_path' : 'text',
    action_id: normalizeLocalActionId(actionId),
    copied_at: new Date().toISOString(),
    ...(filePathPurpose ? {
      relative_path: cleanRelativePath,
      digest_id: sanitizeText(digestId || '').slice(0, 120),
      history_item_key: sanitizeText(historyItemKey || '').slice(0, 160),
      file_version: String(fileVersion || '').trim(),
      digest_file_version: String(digestFileVersion || '').trim(),
      output_dir_identity: normalizeOutputDirRequestIdentity(outputDirIdentity),
      settings_revision: String(settingsRevision || '').trim().slice(0, 320),
      file_ext: path.extname(cleanRelativePath).toLowerCase(),
      file_kind: sanitizeText(fileKind || '').slice(0, 80),
      evidence_ref: localActionEvidenceRef(cleanRelativePath),
    } : {}),
    platform: process.platform,
    method: sanitizeText(copied?.method || evidence.method || 'system_clipboard'),
    local_action_committed: copied?.local_action_committed === true || evidence.local_action_committed === true,
    committed_at: evidence.committed_at || (copied?.local_action_committed === true ? new Date().toISOString() : ''),
    action_state: 'settled',
    verification_pending: false,
    clipboard_verified: copied?.clipboard_verified === true,
    evidence_verified: copied?.clipboard_verified === true,
    cancelled_after_commit: cancelledAfterCommit === true,
    local_action_after_commit_reason: sanitizeText(copied?.local_action_after_commit_reason || evidence.local_action_after_commit_reason || (cancelledAfterCommit ? 'cancelled_after_commit' : '')),
    local_action_after_commit_error: sanitizeLocalActionUserError(copied?.local_action_after_commit_error || evidence.local_action_after_commit_error || ''),
  });
  return rememberLocalActionEvidence(evidence);
}

function previewClipboardSource(value = '') {
  const source = String(value || '').trim();
  if (['live_digest_preview', 'history_rerender_preview'].includes(source)) return source;
  return 'preview';
}

const BROWSER_CLIPBOARD_ACTION_KINDS = new Set(['clipboard_copy', 'preview_clipboard_copy', 'text_clipboard_copy']);
const BROWSER_CLIPBOARD_ACTION_PHASES = new Set(['prepared', 'browser_committed', 'browser_rejected', 'outcome_unknown']);

function normalizeBrowserClipboardActionKind(value = '') {
  const kind = String(value || '').trim();
  return BROWSER_CLIPBOARD_ACTION_KINDS.has(kind) ? kind : '';
}

function normalizeBrowserClipboardActionPhase(value = '') {
  const phase = String(value || '').trim();
  return BROWSER_CLIPBOARD_ACTION_PHASES.has(phase) ? phase : '';
}

function browserClipboardTarget(kind = '', value = {}) {
  const cleanKind = normalizeBrowserClipboardActionKind(kind);
  if (cleanKind === 'clipboard_copy') {
    return {
      digest_id: sanitizeText(value?.digest_id || '').slice(0, 120),
      history_item_key: sanitizeText(value?.history_item_key || value?.history_key || '').slice(0, 160),
      file_version: String(value?.expected_file_version || value?.file_version || '').trim(),
      digest_file_version: String(value?.expected_digest_file_version || value?.digest_file_version || '').trim(),
      output_dir_identity: normalizeOutputDirRequestIdentity(value?.expected_output_dir_identity || value?.output_dir_identity || ''),
      settings_revision: String(value?.expected_settings_revision || value?.settings_revision || '').trim().slice(0, 320),
    };
  }
  if (cleanKind === 'preview_clipboard_copy') {
    return {
      digest_id: sanitizeText(value?.digest_id || '').slice(0, 120),
      history_item_key: sanitizeText(value?.history_item_key || value?.history_key || '').slice(0, 160),
      preview_source: previewClipboardSource(value?.preview_source || value?.source || ''),
    };
  }
  return {
    purpose: String(value?.purpose || 'text') === 'file_path' ? 'file_path' : 'text',
    content_bytes: Math.max(0, Math.min(SYSTEM_TEXT_CLIPBOARD_MAX_BYTES, Number(value?.content_bytes || 0) || 0)),
  };
}

function browserClipboardTargetKey(kind = '', value = {}) {
  return JSON.stringify(browserClipboardTarget(kind, value));
}

function assertBrowserClipboardEvidenceTarget(evidence = null, kind = '', value = {}) {
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return;
  const expectedKind = normalizeBrowserClipboardActionKind(kind);
  const actualKind = normalizeBrowserClipboardActionKind(evidence.kind);
  if (!expectedKind || actualKind !== expectedKind || browserClipboardTargetKey(expectedKind, evidence) !== browserClipboardTargetKey(expectedKind, value)) {
    throw requestValidationError('浏览器剪贴板动作标识已绑定到另一个目标；已拒绝覆盖原动作证据。请刷新页面后重新操作。', 409, 'browser_clipboard_target_mismatch');
  }
}

function prepareBrowserClipboardEvidence(kind = '', actionId = '', value = {}, { file = '' } = {}) {
  const cleanKind = normalizeBrowserClipboardActionKind(kind);
  const target = browserClipboardTarget(cleanKind, value);
  const relativePath = file ? projectRelativePath(file) : '';
  const evidence = {
    kind: cleanKind,
    action_id: normalizeLocalActionId(actionId),
    requested_at: new Date().toISOString(),
    platform: process.platform,
    method: 'browser_clipboard',
    browser_clipboard_phase: 'prepared',
    action_state: 'prepared',
    state_version: 1,
    persisted_state_version: 0,
    client_reported: false,
    browser_clipboard_reported: false,
    local_action_committed: false,
    clipboard_verified: false,
    evidence_verified: false,
    ...target,
  };
  if (relativePath) {
    evidence.relative_path = relativePath;
    evidence.evidence_ref = localActionEvidenceRef(relativePath);
  }
  if (cleanKind === 'preview_clipboard_copy') {
    evidence.untrusted_preview = true;
    evidence.preview_only = true;
    evidence.saved_png_bound = false;
  }
  return rememberLocalActionEvidence(evidence);
}

function transitionBrowserClipboardEvidence(evidence = null, phase = '', value = {}) {
  const cleanPhase = normalizeBrowserClipboardActionPhase(phase);
  if (!evidence || !cleanPhase) return evidence;
  const currentPhase = String(evidence.browser_clipboard_phase || '').trim();
  if (currentPhase === 'browser_committed' && cleanPhase === 'browser_committed') {
    const previousClipboard = normalizedClipboardSize(evidence.clipboard);
    const nextClipboard = normalizedClipboardSize(value?.clipboard);
    if (previousClipboard && nextClipboard && (previousClipboard.width !== nextClipboard.width || previousClipboard.height !== nextClipboard.height)) {
      throw requestValidationError('浏览器剪贴板动作已绑定到另一组图片尺寸；已拒绝覆盖原提交证据。', 409, 'browser_clipboard_transition_conflict');
    }
  }
  if (currentPhase === 'browser_committed' && cleanPhase !== 'browser_committed') return evidence;
  if (currentPhase === 'browser_rejected' && cleanPhase !== 'browser_rejected') return evidence;
  if (cleanPhase === 'prepared') return evidence;
  if (cleanPhase === 'browser_rejected') {
    evidence.browser_clipboard_phase = 'browser_rejected';
    evidence.action_state = 'rejected';
    evidence.state_version = Math.max(2, Number(evidence.state_version || 0) || 0);
    evidence.verification_pending = false;
    evidence.browser_clipboard_error = sanitizeLocalActionUserError(
      value?.error || value?.message || '浏览器拒绝了剪贴板写入。',
    );
    return rememberLocalActionEvidence(evidence);
  }
  if (cleanPhase === 'outcome_unknown') {
    evidence.browser_clipboard_phase = 'outcome_unknown';
    evidence.action_state = 'outcome_unknown';
    evidence.state_version = Math.max(2, Number(evidence.state_version || 0) || 0);
    evidence.verification_pending = false;
    evidence.local_action_after_commit_reason ||= 'browser_clipboard_outcome_unknown';
    evidence.local_action_after_commit_error ||= '页面在浏览器剪贴板写入结果落盘前中断；不会自动重放写入，请粘贴确认后再决定是否重试。';
    return rememberLocalActionEvidence(evidence);
  }
  evidence.browser_clipboard_phase = 'browser_committed';
  evidence.action_state = 'reported';
  evidence.state_version = Math.max(2, Number(evidence.state_version || 0) || 0);
  evidence.copied_at ||= new Date().toISOString();
  evidence.clipboard = normalizedClipboardSize(value?.clipboard) || evidence.clipboard || null;
  evidence.client_reported = true;
  evidence.browser_clipboard_reported = true;
  evidence.verification_pending = false;
  evidence.cancelled_after_commit = value?.cancelled_after_commit === true || evidence.cancelled_after_commit === true;
  if (evidence.cancelled_after_commit) evidence.local_action_after_commit_reason ||= 'cancelled_after_commit';
  return rememberLocalActionEvidence(evidence);
}

function recordOpenOutputEvidence(dir, opener = {}, { actionId = '', outputDirWasMissing = false, outputDirCreated = false, outputDirStatus = '', cancelledAfterCommit = false, outputDirIdentity = '', settingsRevision = '', existingEvidence = null } = {}) {
  const relativePath = projectRelativePath(dir);
  const status = String(outputDirStatus || (outputDirCreated ? 'created' : 'existing')).trim();
  const evidence = existingEvidence && typeof existingEvidence === 'object' && !Array.isArray(existingEvidence)
    ? existingEvidence
    : {};
  const afterCommitReason = sanitizeText(opener?.local_action_after_commit_reason || evidence.local_action_after_commit_reason || (cancelledAfterCommit ? 'cancelled_after_commit' : ''));
  const afterCommitError = sanitizeLocalActionUserError(opener?.local_action_after_commit_error || evidence.local_action_after_commit_error || '');
  const initialVerification = openOutputVerificationPayload(opener);
  const targetWindowHandle = Number(opener?.foreground?.window_handle || evidence._verification_target_window_handle || 0) || 0;
  Object.assign(evidence, {
    kind: 'open_output',
    action_id: normalizeLocalActionId(actionId),
    opened_at: evidence.opened_at || new Date().toISOString(),
    relative_path: relativePath,
    output_dir_identity: normalizeOutputDirRequestIdentity(outputDirIdentity),
    settings_revision: String(settingsRevision || '').trim(),
    evidence_ref: localActionEvidenceRef(relativePath),
    platform: opener?.platform || process.platform,
    opener: opener?.opener || '',
    mode: opener?.mode || 'open_dir',
    reused_existing_window: opener?.reused_existing_window === true,
    started_explorer: opener?.started_explorer === true,
    explorer_keeper_started: opener?.explorer_keeper_started === true,
    explorer_keeper_pid: Number(opener?.explorer_keeper_pid || 0) || 0,
    explorer_keeper_alive: opener?.explorer_keeper_alive === true,
    explorer_keeper_exit_code: opener?.explorer_keeper_exit_code !== null && opener?.explorer_keeper_exit_code !== undefined && Number.isInteger(Number(opener.explorer_keeper_exit_code)) ? Number(opener.explorer_keeper_exit_code) : null,
    launch_status: opener?.launch_status || evidence.launch_status || '',
    activation_retried: opener?.activation_retried === true,
    deferred_foreground_nudge_result: opener?.deferred_foreground_nudge_result === true,
    output_dir_was_missing: outputDirWasMissing === true,
    output_dir_created: outputDirCreated === true,
    output_dir_status: status === 'created' ? 'created' : 'existing',
    cancelled_after_commit: cancelledAfterCommit === true,
    local_action_committed: opener?.local_action_committed === true,
    committed_at: opener?.local_action_committed === true ? (evidence.committed_at || new Date().toISOString()) : '',
    local_action_after_commit_reason: afterCommitReason,
    local_action_after_commit_error: afterCommitError,
    foreground: process.platform === 'win32' ? (opener?.foreground || null) : null,
    tab_ambiguous: opener?.tab_ambiguous === true,
    window_ambiguous: opener?.window_ambiguous === true,
    target_window_count: Number(opener?.target_window_count || 0) || 0,
    explorer_view_count: Number(opener?.explorer_view_count || 0) || 0,
    verified: initialVerification.verified,
    verification_status: initialVerification.status,
    verification: initialVerification.verification,
    _verification_target_path: path.resolve(dir || ''),
    _verification_target_window_handle: targetWindowHandle,
  });
  const evidencePlatform = String(evidence.platform || process.platform || '').trim();
  if (evidencePlatform === 'win32' && evidence.local_action_committed === true) {
    armWindowActionForegroundIntent(evidence, { refresh: true });
    armExplorerForegroundHandoffCheck(evidence);
    refreshOpenOutputEvidenceVerification(evidence);
  }
  const needsVerification = (evidencePlatform === 'win32'
      && evidence.local_action_committed === true
      && evidence.verified !== true)
    || (evidencePlatform !== 'win32'
      && evidence.local_action_committed === true
      && /^running_/.test(String(evidence.launch_status || ''))
      && evidence.detached_observation_settled !== true
      && evidence.local_action_after_commit_reason !== 'failed_after_commit');
  evidence.verification_pending = needsVerification;
  evidence.action_state = needsVerification ? 'committed' : 'settled';
  LAST_OPEN_OUTPUT_EVIDENCE = rememberLocalActionEvidence(evidence);
  if (needsVerification) scheduleOpenOutputVerification(dir, evidence, {
    delayMs: 250,
    activateIfNeeded: windowActionCanRetryForegroundActivation(evidence),
  });
  return LAST_OPEN_OUTPUT_EVIDENCE;
}

