      committedResult = result && typeof result === 'object' && !Array.isArray(result) ? result : null;
      resultCommitted = true;
      await restartPersistedSchedulerIfRunnable(null, { reason: 'manual_run_recovery' }).catch(e => {
        logWarn('scheduler_manual_run_recovery_failed', { error: sanitizeText(e?.message || String(e)) });
      });
