        ok: true,
        item: publicOutputItem({ ...item, cancelled_after_commit: cancelledAfterCommit }),
        redacted,
        cancelled_after_commit: cancelledAfterCommit,
        local_action_committed: true,
        local_action_after_commit_reason: afterCommitReason,
