      if (abort.signal.aborted) throw abort.signal.reason || requestAbortError('历史列表读取已取消。');
      await waitForActiveRetentionCleanup();
      if (abort.signal.aborted) throw abort.signal.reason || requestAbortError('历史列表读取已取消。');
      const history = await listHistory(settings, {
        offset: parsedUrl.searchParams.get('offset') || 0,
        limit: parsedUrl.searchParams.get('limit') || 50,
        cursor: parsedUrl.searchParams.get('cursor') || '',
        searchCursor: parsedUrl.searchParams.get('search_cursor') || '',
        query: parsedUrl.searchParams.get('q') || '',
        filter: parsedUrl.searchParams.get('filter') || 'ok',
        accountId: parsedUrl.searchParams.get('account_id') || parsedUrl.searchParams.get('account') || '',
        bypassCache: ['1', 'true', 'yes'].includes(String(parsedUrl.searchParams.get('refresh') || '').trim().toLowerCase()),
        readOnly: true,
        signal: abort.signal,
      });
