      const expectedFileVersion = String(lookup.expected_file_version || '').trim();
      const currentFileVersion = String(markdownItem.file_version || '').trim();
      if (!currentFileVersion || !outputFileVersionMatches(expectedFileVersion, currentFileVersion)) {
        return sendJson(res, 409, { error: '这条 MD 历史记录已更新，请刷新历史页后重新定位源摘要。', code: 'history_file_changed' });
      }
      const sourceItem = await resolveCurrentHistoryMarkdownSource(settings, markdownItem, { signal: abort.signal });
      throwIfRequestSignalAborted(abort.signal, '源摘要定位已取消。');
