        if (routeRevealOutputTarget) scheduleRevealSelectionVerification(routeRevealOutputTarget, routeRevealOutputEvidence, {
          delayMs: 250,
          activateIfNeeded: windowActionCanRetryForegroundActivation(routeRevealOutputEvidence),
        });
        await persistRecordedLocalActionEvidence(routeRevealOutputEvidence);
        throw localActionOutcomeUnknownError(routeRevealOutputEvidence, error, '打开输出文件');
