        clipboard_verified: evidence.clipboard_verified === true,
        evidence_verified: evidence.evidence_verified === true,
        method: evidence.method || 'system_clipboard',
        cancelled_after_commit: cancelledAfterCommit,
        local_action_after_commit_reason: evidence.local_action_after_commit_reason || '',
        local_action_after_commit_error: evidence.local_action_after_commit_error || '',
        local_action_id: localActionId,
