            ...responseBase,
            clipboard_supported: true,
            clipboard_attempted: true,
            clipboard_error: sanitizeLocalActionUserError(error?.message || String(error)),
            clipboard_error_code: publicApiErrorCode(error?.public_code || error?.code),
            local_action_capability_invalidated: error?.local_action_capability_invalidated === true,
            local_action_id: localActionId,
