          relative_path: projectRelativePath(file),
          digest_id: lookup.digest_id,
          history_item_key: lookup.history_item_key,
          file_version: lookup.expected_file_version,
          digest_file_version: lookup.expected_digest_file_version,
          output_dir_identity: copyOutputDirIdentity,
